    isValidSystemStorageKind,
    kindSubpathSegment,
    sanitizeDocumentId,
    documentRelativePath,
    isForbiddenLegacySegment,
    pathContainsForbiddenLegacySegment,
    CURRENT_SCHEMA_VERSION,
    registerSchemaMigration,
    applySchemaMigrations,
    SystemStorageError,
