/* === gb-owner-key-ui.js === */
;
(function () {
  'use strict';

  let _observer = null;
  let _activeAuditTrigger = null;

  function _esc(value) {
    if (typeof esc === 'function') return esc(value);
    return String(value ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  }

  function _icon(name, size = 14) {
    return typeof lucide === 'function' ? lucide(name, size) : '';
  }

  function _restoreFocus(el) {
    if (!el?.isConnected || typeof el.focus !== 'function') return;
    try { el.focus({ preventScroll: true }); } catch { try { el.focus(); } catch {} }
  }

  function _closeAuditDialog(overlay, trigger = _activeAuditTrigger) {
    if (!overlay?.isConnected) return;
    overlay.remove();
    _activeAuditTrigger = null;
    setTimeout(() => _restoreFocus(trigger), 0);
  }

  async function _promptImportKey() {
    if (typeof cfPrompt === 'function') {
      return await cfPrompt('管理者鍵を貼り付けてください', '', { okLabel: 'インポート' });
    }
    return window.prompt('管理者鍵を貼り付けてください');
  }

  function _isOwner() {
    return window.MeldexKnowledgeCloudStore?.role?.() === 'owner'
      || window.MeldexRuntimeAdapter?.getWorkspaceState?.()?.isOwner === true;
  }

  async function _provider() {
    return window.MeldexStorageAdapter?.getProvider?.() || null;
  }

  function _status(root, text, error) {
    const el = root?.querySelector?.('[data-owner-key-status]');
    if (!el) return;
    el.textContent = text || '';
    el.style.color = error ? 'var(--danger)' : 'var(--fg2)';
  }

  async function _resign(root) {
    const provider = await _provider();
    if (!provider) return { signed: [] };
    const result = await window.MeldexKnowledgeIntegrity?.resignAll?.(provider);
    _status(root, `再署名しました: ${(result?.signed || []).length}件`);
    return result;
  }

  async function _derive(root) {
    if (!_isOwner()) return _status(root, '管理者のみ実行できます', true);
    const pass = root.querySelector('[data-owner-key-passphrase]')?.value || '';
    if (!pass) return _status(root, 'パスフレーズを入力してください', true);
    try {
      await window.MeldexOwnerKeyStore?.deriveFromPassphrase?.(pass);
      await _resign(root);
    } catch (err) {
      _status(root, err?.message || String(err), true);
    }
  }

  async function _rotate(root) {
    if (!_isOwner()) return _status(root, '管理者のみ実行できます', true);
    const ok = typeof cfConfirm === 'function'
      ? await cfConfirm('管理者鍵をローテーションします。既存の署名対象を新しい鍵で再署名しますか？')
      : window.confirm('管理者鍵をローテーションします。既存の署名対象を新しい鍵で再署名しますか？');
    if (!ok) return;
    try {
      await window.MeldexOwnerKeyStore?.createRandomKey?.();
      await _resign(root);
      _status(root, '管理者鍵をローテーションしました');
    } catch (err) {
      _status(root, err?.message || String(err), true);
    }
  }

  async function _export(root) {
    if (!_isOwner()) return _status(root, '管理者のみ実行できます', true);
    try {
      const value = await window.MeldexOwnerKeyStore?.getRawKey?.({ create: false });
      if (!value) return _status(root, '管理者鍵は未設定です', true);
      if (navigator.clipboard?.writeText) {
        await navigator.clipboard.writeText(value);
        _status(root, '管理者鍵をクリップボードへコピーしました');
      } else {
        window.prompt('管理者鍵', value);
        _status(root, '管理者鍵を表示しました');
      }
    } catch (err) {
      _status(root, err?.message || String(err), true);
    }
  }

  function _openRecovery(root) {
    if (!_isOwner()) return _status(root, '管理者のみ実行できます', true);
    const trigger = arguments[1] || root?.querySelector?.('[data-owner-key-action="recovery"]');
    window.MeldexOwnerKeyRecovery?.showRecoveryDialog?.({ trigger });
  }

  async function _import(root) {
    if (!_isOwner()) return _status(root, '管理者のみ実行できます', true);
    const value = await _promptImportKey();
    if (!value) return;
    try {
      await window.MeldexOwnerKeyStore?.setRawKey?.(value.trim());
      await _resign(root);
      _status(root, '管理者鍵をインポートして再署名しました');
    } catch (err) {
      _status(root, err?.message || String(err), true);
    }
  }

  async function _verify(root) {
    try {
      const result = await window.MeldexKnowledgeIntegrity?.checkAll?.();
      if (!result || result.skipped) return _status(root, 'Dropbox provider が未初期化です', true);
      if (result.ok) return _status(root, `署名検証OK (${result.items.length}件)`);
      const missingKey = (result.failed || []).some(item => item?.verification?.missing_key || item?.verification?.reason === 'owner-key-missing');
      if (missingKey) {
        _status(root, '管理者鍵がこの端末にありません。復旧UIを開いてください。', true);
        if (_isOwner()) window.MeldexOwnerKeyRecovery?.showRecoveryDialog?.({ reason: '署名検証に必要な管理者鍵がこの端末にありません。', trigger: root.querySelector('[data-owner-key-action="verify"]') });
        return;
      }
      _status(root, `署名検証NG: ${result.failed.map(item => item.label).join('、')}`, true);
      window.MeldexKnowledgeIntegrity?.openRecoveryDialog?.(result.failed);
    } catch (err) {
      _status(root, err?.message || String(err), true);
    }
  }

  async function _audit(root, trigger) {
    try {
      const provider = await _provider();
      if (!provider) return _status(root, 'Dropbox provider が未初期化です', true);
      const rows = await window.MeldexKnowledgeSignature?.readAudit?.(provider).catch(() => []) || [];
      _openAuditDialog(rows, { trigger });
      _status(root, `監査ログ ${rows.length}件`);
    } catch (err) {
      _status(root, err?.message || String(err), true);
    }
  }

  function _openAuditDialog(rows, options = {}) {
    document.querySelectorAll('.modal-overlay[data-owner-key-audit="1"]').forEach(el => el.remove());
    const trigger = options.trigger || document.activeElement;
    _activeAuditTrigger = trigger && document.contains(trigger) ? trigger : null;
    const overlay = document.createElement('div');
    overlay.className = 'modal-overlay';
    overlay.dataset.ownerKeyAudit = '1';
    overlay.dataset.e2eId = 'owner-key-audit-overlay';
    overlay.innerHTML = `
      <div class="modal gb-owner-key-audit-dialog" role="dialog" aria-modal="true" aria-labelledby="owner-key-audit-title" data-e2e-id="owner-key-audit-dialog">
        <div class="gb-modal-header gb-owner-key-dialog-header">
          <h3 id="owner-key-audit-title" class="gb-modal-title">ナレッジ監査ログ</h3>
          <button type="button" class="gb-btn gb-btn-sm gb-btn-icon gb-owner-key-dialog-close" aria-label="監査ログを閉じる" data-owner-key-audit-close data-e2e-id="owner-key-audit-close">${_icon('x', 14) || '閉じる'}</button>
        </div>
        <div class="gb-modal-body gb-owner-key-audit-body" role="list" data-e2e-id="owner-key-audit-body">
          ${(rows || []).slice().reverse().slice(0, 200).map(row => `
            <div class="gb-owner-key-audit-row" role="listitem" data-e2e-id="owner-key-audit-row">
              <div><strong>${_esc(row.type || 'event')}</strong> <span class="gb-section-desc">${_esc(row.at || '')}</span></div>
              <pre class="gb-owner-key-audit-json">${_esc(JSON.stringify(row, null, 2))}</pre>
            </div>
          `).join('') || '<div class="gb-section-desc">監査ログはまだありません。</div>'}
        </div>
      </div>
    `;
    document.body.appendChild(overlay);
    const close = () => _closeAuditDialog(overlay, _activeAuditTrigger);
    overlay.querySelector('[data-owner-key-audit-close]')?.addEventListener('click', close);
    overlay.addEventListener('click', event => { if (event.target === overlay) close(); });
    overlay.addEventListener('keydown', event => {
      if (event.key !== 'Escape') return;
      event.preventDefault();
      close();
    });
    if (window.GBModalShell?.enhanceOverlay) window.GBModalShell.enhanceOverlay(overlay);
    setTimeout(() => overlay.querySelector('[data-owner-key-audit-close]')?.focus?.({ preventScroll: true }), 0);
    return overlay;
  }

  function _renderSection(panel) {
    if (!panel || panel.querySelector('[data-owner-key-section]')) return;
    const section = document.createElement('section');
    section.className = 'gb-section gb-section--boxed gb-owner-key-section';
    section.dataset.ownerKeySection = '1';
    section.dataset.e2eId = 'owner-key-section';
    section.dataset.settingsView = 'memory';
    section.setAttribute('role', 'region');
    section.setAttribute('aria-labelledby', 'owner-key-section-title');
    const owner = _isOwner();
    section.innerHTML = `
      <div class="gb-section-title gb-owner-key-title" id="owner-key-section-title">${_icon('keyRound', 14)} 管理者鍵 / 改竄検知</div>
      <div class="gb-section-desc">この端末内に暗号化して保存する管理者用の鍵です。 ${fieldHelp('ナレッジ、編集ロック、対象ファイルの署名に使う鍵です。Dropboxには保存されません。')}</div>
      <label class="gb-field-row gb-owner-key-passphrase-row">
        <span class="gb-label gb-owner-key-label">パスフレーズ</span>
        <input type="password" class="gb-input gb-owner-key-passphrase-input" data-setting="owner-key-passphrase" data-owner-key-passphrase data-e2e-id="owner-key-passphrase" aria-label="管理者鍵パスフレーズ" autocomplete="new-password" ${owner ? '' : 'disabled'} placeholder="${_esc(window.MeldexOwnerKeyStore?.PASSPHRASE_MIN_LENGTH || 12)}文字以上">
        <button type="button" class="gb-btn gb-btn-sm gb-owner-key-action" data-setting="owner-key-derive" data-owner-key-action="derive" data-e2e-id="owner-key-derive" aria-label="パスフレーズから導出して再署名" ${owner ? '' : 'disabled'}>導出して再署名</button>
      </label>
      <div class="gb-field-row gb-owner-key-actions">
        <button type="button" class="gb-btn gb-btn-sm gb-btn-quiet gb-owner-key-action" data-setting="owner-key-verify" data-owner-key-action="verify" data-e2e-id="owner-key-verify" aria-label="署名を検証">署名検証</button>
        <button type="button" class="gb-btn gb-btn-sm gb-btn-quiet gb-owner-key-action" data-setting="owner-key-export" data-owner-key-action="export" ${owner ? '' : 'disabled'} data-e2e-id="owner-key-export" aria-label="管理者鍵をコピー">鍵をコピー</button>
        <button type="button" class="gb-btn gb-btn-sm gb-btn-quiet gb-owner-key-action" data-setting="owner-key-import" data-owner-key-action="import" data-e2e-id="owner-key-import" aria-label="管理者鍵をインポート" ${owner ? '' : 'disabled'}>鍵をインポート</button>
        <button type="button" class="gb-btn gb-btn-sm gb-btn-quiet gb-owner-key-action" data-setting="owner-key-rotate" data-owner-key-action="rotate" data-e2e-id="owner-key-rotate" aria-label="管理者鍵をローテーション" ${owner ? '' : 'disabled'}>鍵ローテーション</button>
        <button type="button" class="gb-btn gb-btn-sm gb-btn-quiet gb-owner-key-action" data-setting="owner-key-audit" data-owner-key-action="audit" data-e2e-id="owner-key-audit" aria-label="監査ログを開く">監査ログ</button>
        <button type="button" class="gb-btn gb-btn-sm gb-btn-quiet gb-owner-key-action" data-setting="owner-key-recovery" data-owner-key-action="recovery" ${owner ? '' : 'disabled'} data-e2e-id="owner-key-recovery" aria-label="管理者鍵の復旧UIを開く">復旧UI</button>
      </div>
      <div class="gb-section-desc gb-owner-key-status" data-owner-key-status data-e2e-id="owner-key-status" role="status" aria-live="polite">${owner ? '管理者権限あり' : '閲覧のみ。鍵更新は管理者のみ可能です。'}</div>
    `;
    section.addEventListener('click', event => {
      const trigger = event.target?.closest?.('[data-owner-key-action]');
      const action = trigger?.dataset?.ownerKeyAction;
      if (!action) return;
      if (action === 'derive') _derive(section);
      if (action === 'rotate') _rotate(section);
      if (action === 'export') _export(section);
      if (action === 'import') _import(section);
      if (action === 'verify') _verify(section);
      if (action === 'audit') _audit(section, trigger);
      if (action === 'recovery') _openRecovery(section, trigger);
    });
    panel.appendChild(section);
  }

  function refreshOwnerKeySettingsSection(root) {
    const scope = root || document;
    scope.querySelectorAll?.('.settings-panel[data-panel="LLM"]').forEach(_renderSection);
  }

  function startObserver() {
    refreshOwnerKeySettingsSection(document);
    if (_observer) _observer.disconnect();
    const callback = mutations => {
      for (const mutation of mutations) {
        mutation.addedNodes?.forEach(node => {
          if (node?.nodeType === 1) refreshOwnerKeySettingsSection(node);
        });
      }
    };
    const filter = mutation => Array.from(mutation.addedNodes || []).some(node => {
      if (node?.nodeType !== 1) return false;
      return node.matches?.('.settings-panel[data-panel="LLM"]') || !!node.querySelector?.('.settings-panel[data-panel="LLM"]');
    });
    if (window.GBMutationBus) {
      _observer = window.GBMutationBus.subscribe('owner-key-settings', { filter, callback, throttle: 50 });
    } else {
      _observer = new MutationObserver(callback);
      _observer.observe(document.body, { childList: true, subtree: true });
    }
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', startObserver, { once: true });
  else startObserver();

  window.MeldexOwnerKeyUi = {
    refreshOwnerKeySettingsSection,
    openAuditDialog: _openAuditDialog,
  };
})();

;

/* === gb-data-access-dropbox-collab.js === */
;
(function () {
  const internals = window.__MeldexPwaDataAccessInternals;
  const handlers = window.__MeldexPwaDataAccessExtensions;
  if (!internals || !Array.isArray(handlers)) return;

  const {
    NOT_HANDLED,
    _normalizeFolderPath,
    _joinPath,
    _requirePwaProvider,
    _directoryHandle,
    _listDirectoryEntries,
    _readJsonSafe,
    _validateItemName,
    _pathExists,
    _removeEntry,
    _moveEntry,
  } = internals;

  const CHAT_DIR = '_chat';
  const RESERVED_TOP_ROOMS = new Set(['llm', 'dm', 'group', 'file']);
  const GROUP_MEMBERS_FILE = '_members.json';

  function _jsonString(value) {
    return JSON.stringify(String(value == null ? '' : value));
  }

  function _frontmatterValue(value) {
    const raw = String(value || '').trim();
    if (!raw) return '';
    if ((raw.startsWith('"') && raw.endsWith('"')) || (raw.startsWith("'") && raw.endsWith("'"))) {
      try { return JSON.parse(raw); } catch {}
      return raw.slice(1, -1);
    }
    return raw;
  }

  function _timestampText(value) {
    const text = String(value || '').trim();
    if (/^\d{4}-\d{2}-\d{2}\s+\d{2}:\d{2}:\d{2}/.test(text)) return text.replace(/\s+/, 'T');
    return text;
  }

  function _timestampMillis(value) {
    const text = _timestampText(value);
    if (!text) return null;
    const ms = new Date(text).getTime();
    return Number.isFinite(ms) ? ms : null;
  }

  function _parseMessage(raw, fallbackId, fallbackRoom) {
    const text = String(raw || '');
    const match = text.match(/^\uFEFF?---\r?\n([\s\S]*?)\r?\n---(?:\r?\n|$)/);
    const frontmatter = {};
    let body = text;
    if (match) {
      body = text.slice(match[0].length);
      match[1].split(/\r?\n/).forEach((line) => {
        const m = line.match(/^([^:#]+):\s*(.*)$/);
        if (m) frontmatter[m[1].trim()] = _frontmatterValue(m[2]);
      });
    }
    return {
      id: fallbackId,
      from: frontmatter.from || 'anonymous',
      timestamp: _timestampText(frontmatter.timestamp),
      room: frontmatter.room || fallbackRoom || '',
      text: body.trim(),
    };
  }

  function _currentUser(url, body) {
    const candidate = body?.from || url?.searchParams?.get('_user') || (typeof getUsername === 'function' ? getUsername() : '');
    return String(candidate || 'anonymous').trim() || 'anonymous';
  }

  function _safeRoomSegment(value, fallback) {
    const raw = String(value || '').trim() || fallback || 'general';
    return _validateItemName(raw.replace(/[\\/:*?"<>|]/g, '_'), 'room name');
  }

  function _normalizeDmRoomName(name) {
    return String(name || '').split('__').map(part => part.trim()).filter(Boolean).sort((a, b) => a.localeCompare(b, 'ja')).join('__');
  }

  function _normalizeRoomPath(value, type) {
    const raw = _normalizeFolderPath(value || '');
    const parts = raw.split('/').filter(Boolean);
    if (!parts.length) return type === 'dm' ? '' : 'general';
    if (parts.some(part => part === '.' || part === '..' || part.startsWith('.'))) {
      throw new Error('不正なルームパスです');
    }
    if (parts[0] === CHAT_DIR) parts.shift();
    if (!parts.length) return type === 'dm' ? '' : 'general';
    return parts.join('/');
  }

  function _requestSourceFolder(url, body) {
    const raw = body?.source_folder || body?.sourceFolder || url?.searchParams?.get('source_folder') || '';
    const normalized = _normalizeFolderPath(raw);
    if (!normalized || normalized === '.') return '';
    if (normalized.split('/').filter(Boolean).some(part => part === '.' || part === '..')) throw new Error('source_folder が不正です');
    return normalized;
  }

  function _clientRoomPath(sourceFolder, path) {
    const base = _normalizeFolderPath(sourceFolder);
    const normalized = _normalizeFolderPath(path);
    if (base && normalized.startsWith(base + '/' + CHAT_DIR + '/')) {
      return normalized.slice(base.length + CHAT_DIR.length + 2);
    }
    return normalized;
  }

  function _requireRoomPath(value) {
    const raw = String(value || '').trim();
    if (!raw) throw new Error('room は必須です');
    return _normalizeRoomPath(raw);
  }

  function _roomPathFromCreateBody(body, user) {
    const type = String(body?.type || 'general');
    if (type === 'dm') {
      const roomName = _normalizeDmRoomName(body?.name || '');
      if (!roomName || !roomName.split('__').includes(user)) throw new Error('このDMには参加できません');
      return 'dm/' + _safeRoomSegment(roomName, 'dm');
    }
    if (type === 'group') return 'group/' + _safeRoomSegment(body?.name, 'group');
    if (type === 'file') return 'file/' + _normalizeRoomPath(body?.name || 'file', 'file');
    const general = _safeRoomSegment(body?.name, 'general');
    if (RESERVED_TOP_ROOMS.has(general)) throw new Error('予約済みのルーム名です');
    return general;
  }

  function _roomDir(roomPath, sourceFolder) {
    return _joinPath(sourceFolder, CHAT_DIR, _normalizeRoomPath(roomPath));
  }

  function _roomMeta(roomPath) {
    const normalized = _normalizeRoomPath(roomPath);
    const parts = normalized.split('/').filter(Boolean);
    const category = parts[0] || '';
    const name = parts.length > 1 ? parts.slice(1).join('/') : (parts[0] || 'general');
    const type = category === 'dm' || category === 'group' || category === 'file' ? category : 'general';
    return { name, path: normalized || 'general', type };
  }

  function _isHiddenRoomEntry(entry) {
    return String(entry?.name || '').startsWith('.');
  }

  function _assertMutableRoomPath(roomPath) {
    const parts = _normalizeRoomPath(roomPath).split('/').filter(Boolean);
    if (!parts.length) return;
    if (parts[0] === 'llm' || (parts.length === 1 && RESERVED_TOP_ROOMS.has(parts[0]))) {
      throw new Error('予約済みのチャット保存領域は変更できません');
    }
  }

  function _renamedRoomPath(meta, newName) {
    if (meta.type === 'general') return newName;
    if (meta.type === 'file') {
      const parts = meta.path.split('/').filter(Boolean);
      parts[parts.length - 1] = newName;
      return parts.join('/');
    }
    return meta.type + '/' + newName;
  }

  function _roomMembers(room) {
    return String(room || '').split('/').pop().split('__').map(part => part.trim()).filter(Boolean);
  }

  function _groupMembersPath(roomPath, sourceFolder) {
    return _joinPath(_roomDir(roomPath, sourceFolder), GROUP_MEMBERS_FILE);
  }

  async function _groupMembers(provider, roomPath, sourceFolder) {
    const data = await _readJsonSafe(provider, _groupMembersPath(roomPath, sourceFolder), {});
    const members = Array.isArray(data?.members) ? data.members : [];
    return members.map(member => String(member || '').trim()).filter(Boolean);
  }

  async function _canSeeRoom(provider, meta, user, sourceFolder) {
    if (meta.type === 'group') {
      const members = await _groupMembers(provider, meta.path, sourceFolder);
      return members.includes(user);
    }
    if (meta.type !== 'dm') return true;
    const members = _roomMembers(meta.path);
    return members.length === 2 && members.includes(user);
  }

  async function _assertRoomAccess(provider, roomPath, user, sourceFolder) {
    const meta = _roomMeta(roomPath);
    if (!await _canSeeRoom(provider, meta, user, sourceFolder)) {
      throw new Error(meta.type === 'group' ? 'このグループにはアクセスできません' : 'このDMにはアクセスできません');
    }
    return meta;
  }

  async function _listEntries(provider, path) {
    try {
      return await _listDirectoryEntries(provider, path);
    } catch {
      return [];
    }
  }

  async function _readMessage(provider, roomPath, entry) {
    const sourceFolder = arguments.length >= 4 ? arguments[3] : '';
    const filePath = _joinPath(_roomDir(roomPath, sourceFolder), entry.name);
    const raw = await provider.readText(filePath);
    return _parseMessage(raw, String(entry.name || '').replace(/\.md$/i, ''), roomPath);
  }

  async function _roomSummary(provider, roomPath, sourceFolder) {
    const meta = _roomMeta(roomPath);
    const entries = (await _listEntries(provider, _roomDir(meta.path, sourceFolder)))
      .filter(entry => entry?.handle?.kind === 'file' && /\.md$/i.test(entry.name || ''))
      .sort((a, b) => String(a.name || '').localeCompare(String(b.name || '')));
    let last = null;
    if (entries.length) {
      try { last = await _readMessage(provider, meta.path, entries[entries.length - 1], sourceFolder); } catch {}
    }
    const payload = { ...meta, count: entries.length, last };
    if (meta.type === 'dm') payload.members = _roomMembers(meta.path);
    if (meta.type === 'group') payload.members = await _groupMembers(provider, meta.path, sourceFolder);
    return payload;
  }

  async function _fileRoomPaths(provider, sourceFolder) {
    const basePath = _joinPath(sourceFolder, CHAT_DIR, 'file');
    const paths = [];
    async function walk(path, rel) {
      const entries = await _listEntries(provider, path);
      const dirs = entries.filter(entry => entry?.handle?.kind === 'directory' && !_isHiddenRoomEntry(entry));
      const hasMessages = entries.some(entry => entry?.handle?.kind === 'file' && /\.md$/i.test(entry.name || ''));
      if (rel && (hasMessages || dirs.length === 0)) paths.push('file/' + rel);
      for (const dir of dirs) await walk(_joinPath(path, dir.name), rel ? rel + '/' + dir.name : dir.name);
    }
    await walk(basePath, '');
    return paths;
  }

  async function _listRooms(provider, user, sourceFolder) {
    const rootEntries = await _listEntries(provider, _joinPath(sourceFolder, CHAT_DIR));
    const rooms = [];
    for (const entry of rootEntries) {
      if (entry?.handle?.kind !== 'directory' || RESERVED_TOP_ROOMS.has(entry.name)) continue;
      try {
        const meta = await _roomSummary(provider, entry.name, sourceFolder);
        if (await _canSeeRoom(provider, meta, user, sourceFolder)) rooms.push(meta);
      } catch {}
    }
    for (const category of ['dm', 'group']) {
      const catEntries = await _listEntries(provider, _joinPath(sourceFolder, CHAT_DIR, category));
      for (const entry of catEntries) {
        if (entry?.handle?.kind !== 'directory' || _isHiddenRoomEntry(entry)) continue;
        try {
          const meta = await _roomSummary(provider, category + '/' + entry.name, sourceFolder);
          if (await _canSeeRoom(provider, meta, user, sourceFolder)) rooms.push(meta);
        } catch {}
      }
    }
    for (const roomPath of await _fileRoomPaths(provider, sourceFolder)) {
      const meta = await _roomSummary(provider, roomPath, sourceFolder);
      rooms.push(meta);
    }
    return rooms.sort((a, b) => String(a.path || '').localeCompare(String(b.path || ''), 'ja'));
  }

  async function _writeGroupMembers(provider, roomPath, sourceFolder, user, body) {
    const members = Array.isArray(body?.members) ? body.members : [];
    const clean = Array.from(new Set([user, ...members.map(member => String(member || '').trim()).filter(Boolean)]));
    await provider.writeText(_groupMembersPath(roomPath, sourceFolder), JSON.stringify({ members: clean }, null, 2));
  }

  function _messageMarkdown(roomPath, from, text, timestamp) {
    return [
      '---',
      'type: chat-message',
      'from: ' + _jsonString(from),
      'timestamp: ' + _jsonString(timestamp),
      'room: ' + _jsonString(roomPath),
      '---',
      '',
      String(text || ''),
    ].join('\n');
  }

  function _messageFileName(date) {
    const pad = value => String(value).padStart(2, '0');
    const stamp = date.getFullYear()
      + pad(date.getMonth() + 1)
      + pad(date.getDate())
      + '_'
      + pad(date.getHours())
      + pad(date.getMinutes())
      + pad(date.getSeconds());
    const bytes = new Uint8Array(4);
    if (window.crypto?.getRandomValues) window.crypto.getRandomValues(bytes);
    else bytes.forEach((_, index) => { bytes[index] = Math.floor(Math.random() * 256); });
    const suffix = Array.from(bytes).map(byte => byte.toString(16).padStart(2, '0')).join('');
    return stamp + '_' + suffix + '.md';
  }

  handlers.push(async function _dropboxCollabHandler({ method, body, url, pathname }) {
    if (!/^\/collab(\/|$)/.test(pathname)) return NOT_HANDLED;
    const provider = await _requirePwaProvider(method === 'GET' ? 'read' : 'readwrite');
    const user = _currentUser(url, body);
    const sourceFolder = _requestSourceFolder(url, body || {});

    if (pathname === '/collab/rooms' && method === 'GET') {
      return _listRooms(provider, user, sourceFolder);
    }
    if (pathname === '/collab/rooms' && method === 'POST') {
      const roomPath = _roomPathFromCreateBody(body || {}, user);
      await _directoryHandle(provider, _roomDir(roomPath, sourceFolder), true);
      if (_roomMeta(roomPath).type === 'group') await _writeGroupMembers(provider, roomPath, sourceFolder, user, body || {});
      return { ok: true, path: roomPath };
    }
    if (pathname === '/collab/rooms/rename' && method === 'POST') {
      const oldPath = _requireRoomPath(body?.path || '');
      _assertMutableRoomPath(oldPath);
      const meta = await _assertRoomAccess(provider, oldPath, user, sourceFolder);
      if (meta.type === 'dm') throw new Error('DMはリネームできません');
      const newName = _safeRoomSegment(body?.new_name, 'general');
      if (meta.type === 'general' && RESERVED_TOP_ROOMS.has(newName)) throw new Error('予約済みのルーム名です');
      const newPath = _renamedRoomPath(meta, newName);
      if (await _pathExists(provider, _roomDir(newPath, sourceFolder))) throw new Error('同名のルームが既に存在します');
      await _moveEntry(provider, _roomDir(oldPath, sourceFolder), _roomDir(newPath, sourceFolder));
      return { ok: true, path: newPath, name: newName };
    }
    if (pathname === '/collab/rooms' && method === 'DELETE') {
      const roomPath = _requireRoomPath(url.searchParams.get('path') || body?.path || '');
      _assertMutableRoomPath(roomPath);
      await _assertRoomAccess(provider, roomPath, user, sourceFolder);
      await _removeEntry(provider, _roomDir(roomPath, sourceFolder));
      return { ok: true };
    }
    if (pathname === '/collab/messages' && method === 'GET') {
      const roomPath = _requireRoomPath(url.searchParams.get('room') || 'general');
      await _assertRoomAccess(provider, roomPath, user, sourceFolder);
      const since = String(url.searchParams.get('since') || '');
      const sinceMs = _timestampMillis(since);
      const limit = Math.max(1, Math.min(500, Number(url.searchParams.get('limit') || 50) || 50));
      const entries = (await _listEntries(provider, _roomDir(roomPath, sourceFolder)))
        .filter(entry => entry?.handle?.kind === 'file' && /\.md$/i.test(entry.name || ''))
        .sort((a, b) => String(a.name || '').localeCompare(String(b.name || '')));
      const messages = [];
      for (const entry of entries) {
        try {
          const message = await _readMessage(provider, roomPath, entry, sourceFolder);
          const messageMs = _timestampMillis(message.timestamp);
          if (!since
            || (sinceMs != null && messageMs != null && messageMs > sinceMs)
            || (sinceMs == null && String(message.timestamp || '') > since)) messages.push(message);
        } catch {}
      }
      return messages.slice(-limit);
    }
    if (pathname === '/collab/send' && method === 'POST') {
      const roomPath = _requireRoomPath(body?.room || 'general');
      await _assertRoomAccess(provider, roomPath, user, sourceFolder);
      const text = String(body?.text || '');
      if (!text) throw new Error('text は必須');
      const roomDir = _roomDir(roomPath, sourceFolder);
      await _directoryHandle(provider, roomDir, true);
      const now = new Date();
      const timestamp = now.toISOString();
      const fileName = _messageFileName(now);
      const filePath = _joinPath(roomDir, fileName);
      await provider.writeText(filePath, _messageMarkdown(roomPath, user, text, timestamp));
      return { ok: true, id: fileName.replace(/\.md$/i, ''), timestamp };
    }

    return NOT_HANDLED;
  });

  window.MeldexDropboxCollabDataAccess = { CHAT_DIR };
})();

;

/* === gb-data-access-dropbox-chat.js === */
;
(function () {
  'use strict';

  const internals = window.__MeldexPwaDataAccessInternals;
  const handlers = window.__MeldexPwaDataAccessExtensions;
  if (!internals || !Array.isArray(handlers)) return;

  const {
    NOT_HANDLED,
    _normalizeFolderPath,
    _joinPath,
    _dirname,
    _basename,
    _requirePwaProvider,
    _directoryHandle,
    _listDirectoryEntries,
    _fileStats,
  } = internals;

  const PWA_CHAT_LLM_DIR = '_chat/llm';
  const CHAT_SECTION_RE = /^###?\s+(User|Assistant)\r?\n/gm;

  async function _llmConfigShape() {
    const configured = await window.MeldexLlmKeys?.configuredProviders?.().catch(() => ({})) || {};
    return {
      providers: {
        gemini: { available: true, configured: !!configured.gemini, localConfigured: !!configured.gemini },
        anthropic: { available: true, configured: !!configured.anthropic, localConfigured: !!configured.anthropic },
        openai: { available: true, configured: !!configured.openai, localConfigured: !!configured.openai },
      },
    };
  }

  function _chatMessageText(content) {
    if (typeof content === 'string') return content;
    if (Array.isArray(content)) {
      return content.map(part => {
        if (!part || typeof part !== 'object') return '';
        if (part.type === 'text') return String(part.text || '');
        const name = part.name || part.path || part.url || part.mimeType || part.type || 'attachment';
        return `[${part.type === 'document' ? 'PDF' : '添付'}: ${name}]`;
      }).filter(Boolean).join('\n');
    }
    return String(content || '');
  }

  function _requestSourceFolder(url, body) {
    const raw = body?.source_folder || body?.sourceFolder || url?.searchParams?.get('source_folder') || '';
    const normalized = _normalizeFolderPath(raw);
    if (!normalized || normalized === '.') return '';
    _assertSafeChatPath(normalized, 'source_folder');
    return normalized;
  }

  function _requestWorkspaceId(url, body) {
    return String(
      body?.workspace_id
      || body?.workspaceId
      || url?.searchParams?.get('workspace_id')
      || '',
    ).trim();
  }

  async function _requestChatScopeFolder(url, body) {
    const workspaceId = _requestWorkspaceId(url, body);
    if (!workspaceId) return _requestSourceFolder(url, body);
    const resolver = internals._resolveCloudWorkspaceFolder;
    if (typeof resolver !== 'function') throw new Error('ワークスペースを読み込めません');
    const normalized = _normalizeFolderPath(await resolver(workspaceId));
    if (!normalized || normalized === '.') throw new Error('ワークスペースのDropboxフォルダが設定されていません');
    _assertSafeChatPath(normalized, 'workspace_folder');
    return normalized;
  }

  function _assertSafeChatPath(path, field) {
    const parts = _normalizeFolderPath(path).split('/').filter(Boolean);
    if (parts.some(part => part === '.' || part === '..')) throw new Error(`${field || 'path'} が不正です`);
  }

  function _sourcePath(sourceFolder, path) {
    const base = _normalizeFolderPath(sourceFolder);
    const rel = _normalizeFolderPath(path);
    _assertSafeChatPath(rel, 'path');
    if (!base) return rel;
    if (rel === base || rel.startsWith(base + '/')) return rel;
    return _joinPath(base, rel);
  }

  function _clientPath(sourceFolder, path) {
    const base = _normalizeFolderPath(sourceFolder);
    const normalized = _normalizeFolderPath(path);
    if (base && normalized.startsWith(base + '/')) return normalized.slice(base.length + 1);
    return normalized;
  }

  function _llmDir(sourceFolder) {
    return _sourcePath(sourceFolder, PWA_CHAT_LLM_DIR);
  }

  function _resolveChatPath(sourceFolder, path) {
    const normalized = _normalizeFolderPath(path);
    if (!normalized) throw new Error('path は必須です');
    const llmDir = _llmDir(sourceFolder);
    const scopedPath = _sourcePath(sourceFolder, normalized);
    if (!scopedPath.startsWith(llmDir + '/')) throw new Error('_chat/llm 配下の .md パスを指定してください');
    if (!/\.md$/i.test(scopedPath)) throw new Error('_chat/llm 配下の .md パスを指定してください');
    return scopedPath;
  }

  function _chatNormalizeMessage(message, options = {}) {
    const msg = message && typeof message === 'object' ? message : {};
    const clean = {
      role: String(msg.role || 'user'),
      content: msg.content == null ? '' : msg.content,
      msg_id: String(msg.msg_id || ('msg_' + Math.random().toString(16).slice(2, 10).padEnd(8, '0'))),
    };
    ['timestamp', 'provider', 'model'].forEach(key => {
      const value = String(msg[key] || '').trim();
      if (value) clean[key] = value;
    });
    ['citations', 'code_exec_blocks', 'artifacts'].forEach(key => {
      if (Array.isArray(msg[key])) clean[key] = msg[key];
    });
    if (msg.usage && typeof msg.usage === 'object' && !Array.isArray(msg.usage)) clean.usage = msg.usage;
    if (msg.aborted === true) clean.aborted = true;
    if (str(msg.thinking).trim()) clean.thinking = str(msg.thinking).trim();
    if (str(msg.tool_audit_warning).trim()) clean.tool_audit_warning = str(msg.tool_audit_warning).trim();
    if (msg.compressed === true) clean.compressed = true;
    if (msg.compressed_summary === true) {
      clean.compressed_summary = true;
      clean.original_message_count = Number(msg.original_message_count || 0) || 0;
      if (Array.isArray(msg.original_messages) && options.includeOriginals !== false) {
        clean.original_messages = msg.original_messages.map(item => _chatNormalizeMessage(item, { includeOriginals: false }));
        if (!clean.original_message_count) clean.original_message_count = clean.original_messages.length;
      }
    }
    return clean;
  }

  function str(value) {
    return String(value == null ? '' : value);
  }

  function _yamlString(value) {
    return JSON.stringify(String(value || ''));
  }

  function _chatDocumentFromPayload(body) {
    const messages = (Array.isArray(body?.messages) ? body.messages : []).map(_chatNormalizeMessage);
    const archivedHistory = _chatArchivedHistory(messages, body?.archived_history);
    const frontmatter = [
      '---',
      'type: "chat"',
      'provider: ' + _yamlString(body?.provider || ''),
      'model: ' + _yamlString(body?.model || ''),
      'created: ' + _yamlString(body?._preservedCreated || new Date().toISOString()),
      'tags: ' + JSON.stringify(Array.isArray(body?.tags) ? body.tags : []),
    ];
    const title = String(body?.title || '').trim();
    const targetPath = String(body?.targetPath || body?.target_path || '').trim();
    const targetId = String(body?.targetId || body?.target_id || '').trim();
    if (title) frontmatter.push('title: ' + _yamlString(title));
    if (targetPath) frontmatter.push('targetPath: ' + _yamlString(targetPath));
    if (targetId) frontmatter.push('targetId: ' + _yamlString(targetId));
    if (archivedHistory.length) frontmatter.push('archived_history: ' + JSON.stringify(archivedHistory));
    frontmatter.push('messages: ' + JSON.stringify(messages), '---', '');
    const bodyLines = messages.map(message => {
      const role = message.role === 'assistant' ? 'Assistant' : 'User';
      return `### ${role}\n${_chatMessageText(message.content)}\n`;
    });
    return frontmatter.join('\n') + '\n' + bodyLines.join('\n');
  }

  function _chatArchivedHistory(messages, existing) {
    const archived = Array.isArray(existing) ? existing.filter(item => item && typeof item === 'object') : [];
    const seen = new Set(archived.map(item => String(item.summary_msg_id || '')).filter(Boolean));
    messages.forEach(message => {
      if (!message || message.compressed_summary !== true || !Array.isArray(message.original_messages) || !message.original_messages.length) return;
      const key = String(message.msg_id || '');
      if (key && seen.has(key)) return;
      archived.push({
        summary_msg_id: key,
        original_message_count: Number(message.original_message_count || message.original_messages.length) || message.original_messages.length,
        messages: message.original_messages,
      });
      if (key) seen.add(key);
    });
    return archived;
  }

  function _parsePwaChatFrontmatter(raw) {
    const text = String(raw || '');
    const match = text.match(/^\uFEFF?---\r?\n([\s\S]*?)\r?\n---(?:\r?\n|$)/);
    if (!match) return { frontmatter: {}, body: text, valid: false };
    const fm = {};
    match[1].split(/\r?\n/).forEach(line => {
      if (!/^[A-Za-z_][A-Za-z0-9_-]*\s*:/.test(line)) return;
      const idx = line.indexOf(':');
      if (idx <= 0) return;
      const key = line.slice(0, idx).trim();
      const value = line.slice(idx + 1).trim();
      if (!key) return;
      if (!value) { fm[key] = ''; return; }
      try { fm[key] = JSON.parse(value); }
      catch { fm[key] = value.replace(/^['"]|['"]$/g, ''); }
    });
    const yamlLite = _yamlLiteObject(match[1]);
    Object.entries(yamlLite).forEach(([key, value]) => {
      if (Array.isArray(value) || (value && typeof value === 'object')) fm[key] = value;
      else if (!Object.prototype.hasOwnProperty.call(fm, key)) fm[key] = value;
    });
    return {
      frontmatter: fm,
      body: text.slice(match[0].length),
      valid: String(fm.type || 'chat') === 'chat' && Object.keys(fm).length > 0,
    };
  }

  function _yamlLiteObject(source) {
    const lines = String(source || '').replace(/\r\n/g, '\n').replace(/\r/g, '\n').split('\n');
    const parsed = _yamlLiteBlock(lines, 0, 0).value;
    return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {};
  }

  function _yamlLiteIndent(line) {
    return (String(line || '').match(/^ */) || [''])[0].length;
  }

  function _yamlLiteNextIndent(lines, index, minIndent) {
    for (let i = index; i < lines.length; i += 1) {
      if (!String(lines[i] || '').trim()) continue;
      const indent = _yamlLiteIndent(lines[i]);
      if (indent === minIndent && String(lines[i]).slice(indent).startsWith('- ')) return indent;
      if (indent > minIndent) return indent;
      return minIndent + 2;
    }
    return minIndent + 2;
  }

  function _yamlLiteScalar(raw) {
    const value = String(raw == null ? '' : raw).trim();
    if (!value || value === 'null' || value === '~') return '';
    if (value === 'true') return true;
    if (value === 'false') return false;
    if (/^-?\d+(?:\.\d+)?$/.test(value)) return Number(value);
    try { return JSON.parse(value); } catch {}
    if (value.startsWith("'") && value.endsWith("'")) return value.slice(1, -1).replace(/''/g, "'");
    if (value.startsWith('"') && value.endsWith('"')) return value.slice(1, -1);
    return value.replace(/^['"]|['"]$/g, '');
  }

  function _yamlLitePair(text) {
    const match = String(text || '').match(/^([^:#][^:\n]*):\s*(.*)$/);
    return match ? [match[1].trim(), match[2]] : null;
  }

  function _yamlLiteAssign(target, key, rest, lines, index, indent) {
    if (rest && rest.trim()) return { value: _yamlLiteScalar(rest), next: index + 1 };
    const childIndent = _yamlLiteNextIndent(lines, index + 1, indent);
    const child = _yamlLiteBlock(lines, index + 1, childIndent);
    return { value: child.value, next: child.next };
  }

  function _yamlLiteBlock(lines, start, indent) {
    let index = start;
    while (index < lines.length && !String(lines[index] || '').trim()) index += 1;
    if (index >= lines.length || _yamlLiteIndent(lines[index]) < indent) return { value: {}, next: index };
    const isList = _yamlLiteIndent(lines[index]) === indent && String(lines[index]).slice(indent).startsWith('- ');
    if (isList) {
      const list = [];
      while (index < lines.length) {
        const line = String(lines[index] || '');
        if (!line.trim()) { index += 1; continue; }
        const currentIndent = _yamlLiteIndent(line);
        if (currentIndent < indent) break;
        if (currentIndent > indent) { index += 1; continue; }
        const trimmed = line.slice(indent);
        if (!trimmed.startsWith('- ')) break;
        const rest = trimmed.slice(2);
        const pair = _yamlLitePair(rest);
        if (pair) {
          const item = {};
          const assigned = _yamlLiteAssign(item, pair[0], pair[1], lines, index, indent);
          item[pair[0]] = assigned.value;
          index = assigned.next;
          const childIndent = _yamlLiteNextIndent(lines, index, indent);
          const child = _yamlLiteBlock(lines, index, childIndent);
          if (child.value && typeof child.value === 'object' && !Array.isArray(child.value)) Object.assign(item, child.value);
          index = child.next;
          list.push(item);
        } else if (rest.trim()) {
          list.push(_yamlLiteScalar(rest));
          index += 1;
        } else {
          const childIndent = _yamlLiteNextIndent(lines, index + 1, indent);
          const child = _yamlLiteBlock(lines, index + 1, childIndent);
          list.push(child.value);
          index = child.next;
        }
      }
      return { value: list, next: index };
    }
    const obj = {};
    while (index < lines.length) {
      const line = String(lines[index] || '');
      if (!line.trim()) { index += 1; continue; }
      const currentIndent = _yamlLiteIndent(line);
      if (currentIndent < indent) break;
      if (currentIndent > indent) { index += 1; continue; }
      const pair = _yamlLitePair(line.slice(indent));
      if (!pair) break;
      const assigned = _yamlLiteAssign(obj, pair[0], pair[1], lines, index, indent);
      obj[pair[0]] = assigned.value;
      index = assigned.next;
    }
    return { value: obj, next: index };
  }

  function _messagesFromChatBody(body) {
    const text = String(body || '');
    const matches = Array.from(text.matchAll(CHAT_SECTION_RE));
    if (!matches.length) return [];
    const messages = [];
    for (let i = 0; i < matches.length; i += 1) {
      const match = matches[i];
      const next = matches[i + 1];
      const contentStart = match.index + match[0].length;
      const contentEnd = next ? next.index : text.length;
      const content = text.slice(contentStart, contentEnd).trim();
      messages.push({
        role: match[1] === 'Assistant' ? 'assistant' : 'user',
        content,
      });
    }
    return messages.map(_chatNormalizeMessage);
  }

  function _shouldUseBodyChatMessages(frontmatterMessages, bodyMessages) {
    if (!bodyMessages.length) return false;
    if (!frontmatterMessages.length) return true;
    if (bodyMessages.length > frontmatterMessages.length) return true;
    for (let i = 0; i < Math.min(frontmatterMessages.length, bodyMessages.length); i += 1) {
      const front = frontmatterMessages[i] || {};
      const body = bodyMessages[i] || {};
      if (front.role !== body.role) continue;
      if (typeof front.content !== 'string') continue;
      const frontText = front.content.trim();
      const bodyText = typeof body.content === 'string' ? body.content.trim() : '';
      if (/^[|>][-+]?$/.test(frontText) && bodyText) return true;
      if (!frontText && bodyText) return true;
      if (frontText && bodyText.length > frontText.length && bodyText.startsWith(frontText)) return true;
    }
    return false;
  }

  function _messagesFromParsedChat(parsed) {
    const bodyMessages = _messagesFromChatBody(parsed.body);
    if (Array.isArray(parsed.frontmatter.messages)) {
      const frontmatterMessages = parsed.frontmatter.messages.map(_chatNormalizeMessage);
      return _shouldUseBodyChatMessages(frontmatterMessages, bodyMessages) ? bodyMessages : frontmatterMessages;
    }
    return bodyMessages;
  }

  async function _listPwaChatFiles(provider, sourceFolder) {
    const files = [];
    const rootEntries = await _listDirectoryEntries(provider, _llmDir(sourceFolder)).catch(() => []);
    for (const entry of rootEntries) {
      const path = _joinPath(_llmDir(sourceFolder), entry.name);
      if (entry.handle.kind === 'file' && /\.md$/i.test(entry.name)) {
        files.push({ path, handle: entry.handle });
      } else if (entry.handle.kind === 'directory') {
        const childEntries = await _listDirectoryEntries(provider, path).catch(() => []);
        childEntries.forEach(child => {
          if (child.handle.kind === 'file' && /\.md$/i.test(child.name)) {
            files.push({ path: _joinPath(path, child.name), handle: child.handle });
          }
        });
      }
    }
    return files;
  }

  async function _savePwaChat(provider, body, sourceFolder) {
    const savePath = _resolveChatPath(sourceFolder, body?.path || '');
    await _directoryHandle(provider, _dirname(savePath), true);
    let preservedCreated = '';
    try {
      const existing = _parsePwaChatFrontmatter(await provider.readText(savePath));
      preservedCreated = String(existing.frontmatter.created || '');
    } catch {
      // 初回保存では既存ファイルがないため、そのまま新しい作成日時を使う。
    }
    await provider.writeText(savePath, _chatDocumentFromPayload({ ...(body || {}), _preservedCreated: preservedCreated }));
    const result = { ok: true, path: _clientPath(sourceFolder, savePath), user: String(body?.user || '') };
    const extractor = window.MeldexKnowledgeCloudExtractor;
    if (typeof extractor?.extractAfterChatSave === 'function') {
      try {
        result.knowledge = await extractor.extractAfterChatSave(provider, { ...(body || {}), path: savePath });
      } catch (error) {
        result.knowledge = { ok: false, error: error?.message || String(error) };
      }
    }
    return result;
  }

  async function _loadPwaChat(provider, path, sourceFolder) {
    const chatPath = _resolveChatPath(sourceFolder, path || '');
    const raw = await provider.readText(chatPath);
    const parsed = _parsePwaChatFrontmatter(raw);
    const messages = _messagesFromParsedChat(parsed);
    delete parsed.frontmatter.messages;
    return { frontmatter: parsed.frontmatter, messages };
  }

  async function _readPwaChatHistoryRow(provider, sourceFolder, file) {
    const raw = await provider.readText(file.path);
    const parsed = _parsePwaChatFrontmatter(raw);
    if (!parsed.valid) throw new Error('チャットのフロントマターを読み込めません');
    const stats = await _fileStats(file.handle).catch(() => ({ modifiedMs: 0, modified: '' }));
    const messages = _messagesFromParsedChat(parsed);
    const path = _clientPath(sourceFolder, file.path);
    const modifiedMs = Number(stats.modifiedMs || 0);
    return {
      id: path,
      name: _basename(file.path).replace(/\.md$/i, ''),
      path,
      title: String(parsed.frontmatter.title || ''),
      created: String(parsed.frontmatter.created || ''),
      targetPath: String(parsed.frontmatter.targetPath || ''),
      targetId: String(parsed.frontmatter.targetId || ''),
      provider: String(parsed.frontmatter.provider || ''),
      model: String(parsed.frontmatter.model || ''),
      messageCount: messages.length,
      modified: String(stats.modified || '') || (modifiedMs > 0 ? new Date(modifiedMs).toISOString() : ''),
      _modifiedMs: modifiedMs,
    };
  }

  async function _chatHistoryRows(provider, sourceFolder) {
    const files = await _listPwaChatFiles(provider, sourceFolder);
    const results = new Array(files.length);
    let cursor = 0;
    const worker = async () => {
      while (cursor < files.length) {
        const index = cursor;
        cursor += 1;
        try {
          results[index] = await _readPwaChatHistoryRow(provider, sourceFolder, files[index]);
        } catch (error) {
          results[index] = { _unreadable: true, _error: error?.message || String(error) };
        }
      }
    };
    const workerCount = Math.min(6, files.length);
    await Promise.all(Array.from({ length: workerCount }, () => worker()));
    const rows = results.filter(row => row && !row._unreadable);
    const unreadableCount = results.filter(row => row?._unreadable).length;
    rows.sort((a, b) => {
      const timeDiff = (b._modifiedMs || 0) - (a._modifiedMs || 0);
      return timeDiff || String(b.path || '').localeCompare(String(a.path || ''), 'ja', { numeric: true });
    });
    return { rows, unreadableCount };
  }

  async function _listPwaChats(provider, sourceFolder) {
    const { rows } = await _chatHistoryRows(provider, sourceFolder);
    return rows.slice(0, 50).map(({ _modifiedMs, ...row }) => ({
      ...row,
      modified: _modifiedMs || 0,
    }));
  }

  async function _pwaChatHistory(provider, sourceFolder) {
    const { rows, unreadableCount } = await _chatHistoryRows(provider, sourceFolder);
    const items = rows.map(({ name, _modifiedMs, ...row }) => row);
    return { items, total: items.length, unreadableCount };
  }

  async function _searchPwaChats(provider, query, sourceFolder) {
    const q = String(query || '').trim().toLowerCase();
    if (!q) return { results: [] };
    const results = [];
    const files = await _listPwaChatFiles(provider, sourceFolder);
    for (const file of files) {
      try {
        const raw = await provider.readText(file.path);
        const parsed = _parsePwaChatFrontmatter(raw);
        const data = { frontmatter: parsed.frontmatter, messages: _messagesFromParsedChat(parsed) };
        for (const message of data.messages || []) {
          const text = _chatMessageText(message.content);
          const idx = text.toLowerCase().indexOf(q);
          if (idx < 0) continue;
          const snippet = text.slice(Math.max(0, idx - 40), idx + q.length + 60);
          const clientPath = _clientPath(sourceFolder, file.path);
          const stats = await _fileStats(file.handle).catch(() => ({ modifiedMs: 0 }));
          results.push({ path: clientPath, title: String(data.frontmatter.title || '') || _basename(clientPath), snippet, modified: stats.modifiedMs || 0 });
          break;
        }
      } catch {}
    }
    results.sort((a, b) => (b.modified || 0) - (a.modified || 0));
    return { results: results.slice(0, 30).map(({ modified, ...row }) => row) };
  }

  handlers.push(async ({ method, body, url, pathname }) => {
    if (!pathname.startsWith('/chat/')) return NOT_HANDLED;
    if (pathname === '/chat/config' && method === 'GET') return _llmConfigShape();
    if (pathname === '/chat/config' && (method === 'PUT' || method === 'POST')) return { ok: false, unsupported: true };
    if (pathname === '/chat/stream' && method === 'POST') return { ok: true, direct_client_stream: true };
    const sourceFolder = await _requestChatScopeFolder(url, body || {});
    if (pathname === '/chat/list' && method === 'GET') {
      const provider = await _requirePwaProvider('read');
      return _listPwaChats(provider, sourceFolder);
    }
    if (pathname === '/chat/history' && method === 'GET') {
      const provider = await _requirePwaProvider('read');
      return _pwaChatHistory(provider, sourceFolder);
    }
    if (pathname === '/chat/search' && method === 'GET') {
      const provider = await _requirePwaProvider('read');
      return _searchPwaChats(provider, url.searchParams.get('q') || '', sourceFolder);
    }
    if (pathname === '/chat/load' && method === 'GET') {
      const provider = await _requirePwaProvider('read');
      return _loadPwaChat(provider, url.searchParams.get('path') || '', sourceFolder);
    }
    if (pathname === '/chat/save' && method === 'POST') {
      const provider = await _requirePwaProvider('readwrite');
      return _savePwaChat(provider, body || {}, sourceFolder);
    }
    return NOT_HANDLED;
  });
})();

;

/* === gb-workspace-cli-relay.js === */
;
(function () {
  const internals = window.__MeldexPwaDataAccessInternals;
  const handlers = window.__MeldexPwaDataAccessExtensions;
  if (!internals || !Array.isArray(handlers)) return;

  const {
    NOT_HANDLED,
    _normalizeFolderPath,
    _joinPath,
    _requirePwaProvider,
    _directoryHandle,
    _readJsonSafe,
    _validateItemName,
  } = internals;

  const CHAT_DIR = '_chat';
  const REQUEST_DIR = '_chat/workspace-cli/requests';
  const PROVIDER_LABELS = {
    codex: 'Codex CLI',
    claude_code: 'Claude Code',
    antigravity_cli: 'Antigravity CLI',
  };
  const ADMIN_ROLES = new Set(['owner', 'admin']);

  function _jsonString(value) {
    return JSON.stringify(String(value == null ? '' : value));
  }

  function _currentUser(url, body) {
    const candidate = body?.from || url?.searchParams?.get('_user') || (typeof getUsername === 'function' ? getUsername() : '');
    return String(candidate || 'anonymous').trim() || 'anonymous';
  }

  function _isAdminRole(role) {
    return ADMIN_ROLES.has(String(role || '').trim().toLowerCase());
  }

  function _currentWorkspaceCliRole(sourceFolder) {
    try {
      if (typeof getMyRoleForPath === 'function') return String(getMyRoleForPath(sourceFolder || '') || '').trim().toLowerCase();
    } catch {}
    try {
      if (typeof _myTeamRole !== 'undefined') return String(_myTeamRole || '').trim().toLowerCase();
    } catch {}
    return '';
  }

  function _requestSourceFolder(url, body) {
    const raw = body?.source_folder || body?.sourceFolder || url?.searchParams?.get('source_folder') || '';
    const normalized = _normalizeFolderPath(raw);
    if (!normalized || normalized === '.') return '';
    if (normalized.split('/').filter(Boolean).some(part => part === '.' || part === '..')) throw new Error('source_folder が不正です');
    return normalized;
  }

  function _safeRoomSegment(value, fallback) {
    const raw = String(value || '').trim() || fallback || 'general';
    if (raw === '.' || raw === '..' || raw.startsWith('.')) throw new Error('不正なルームパスです');
    return _validateItemName(raw.replace(/[\\/:*?"<>|]/g, '_'), 'room name');
  }

  function _normalizeDmRoomName(name) {
    const parts = String(name || '').split('__').map(part => part.trim()).filter(Boolean).sort((a, b) => a.localeCompare(b, 'ja'));
    if (parts.length !== 2) throw new Error('DMルーム名が不正です');
    return parts.join('__');
  }

  function _normalizeRoomPath(value) {
    const raw = _normalizeFolderPath(value || '');
    const parts = raw.split('/').filter(Boolean);
    if (!parts.length) return 'general';
    if (parts.some(part => part === '.' || part === '..' || part.startsWith('.'))) {
      throw new Error('不正なルームパスです');
    }
    if (parts[0] === CHAT_DIR) parts.shift();
    if (!parts.length) return 'general';
    if (parts.length >= 2 && ['dm', 'group', 'file'].includes(parts[0])) {
      const prefix = parts[0];
      const safeParts = parts.slice(1).map(part => _safeRoomSegment(part, prefix));
      if (prefix === 'dm') return 'dm/' + _normalizeDmRoomName(safeParts.join('__'));
      if (prefix === 'group') return 'group/' + safeParts.join('__');
      return 'file/' + safeParts.join('/');
    }
    if (parts.length === 1 && ['llm', 'dm', 'group', 'file'].includes(parts[0])) throw new Error('予約済みのルーム名です');
    return _safeRoomSegment(parts.join('_'), 'general');
  }

  function _roomDir(roomPath, sourceFolder) {
    return _joinPath(sourceFolder, CHAT_DIR, _normalizeRoomPath(roomPath));
  }

  function _roomMembers(room) {
    return String(room || '').split('/').pop().split('__').map(part => part.trim()).filter(Boolean);
  }

  async function _groupMembers(provider, roomPath, sourceFolder) {
    const data = await _readJsonSafe(provider, _joinPath(_roomDir(roomPath, sourceFolder), '_members.json'), {});
    const members = Array.isArray(data?.members) ? data.members : [];
    return members.map(member => String(member || '').trim()).filter(Boolean);
  }

  async function _assertRoomAccess(provider, roomPath, user, sourceFolder) {
    const normalized = _normalizeRoomPath(roomPath);
    const parts = normalized.split('/').filter(Boolean);
    if (parts[0] === 'dm') {
      const members = _roomMembers(normalized);
      if (members.length !== 2 || !members.includes(user)) throw new Error('このDMにはアクセスできません');
    }
    if (parts[0] === 'group') {
      const members = await _groupMembers(provider, normalized, sourceFolder);
      if (!members.includes(user)) throw new Error('このグループにはアクセスできません');
    }
    return normalized;
  }

  function _messageMarkdown(roomPath, from, text, timestamp) {
    return [
      '---',
      'type: chat-message',
      'from: ' + _jsonString(from),
      'timestamp: ' + _jsonString(timestamp),
      'room: ' + _jsonString(roomPath),
      '---',
      '',
      String(text || ''),
    ].join('\n');
  }

  function _randomHex(size) {
    const bytes = new Uint8Array(size);
    if (window.crypto?.getRandomValues) window.crypto.getRandomValues(bytes);
    else bytes.forEach((_, index) => { bytes[index] = Math.floor(Math.random() * 256); });
    return Array.from(bytes).map(byte => byte.toString(16).padStart(2, '0')).join('');
  }

  function _messageFileName(date) {
    const pad = value => String(value).padStart(2, '0');
    return date.getFullYear()
      + pad(date.getMonth() + 1)
      + pad(date.getDate())
      + '_'
      + pad(date.getHours())
      + pad(date.getMinutes())
      + pad(date.getSeconds())
      + '_' + _randomHex(4) + '.md';
  }

  function _requestId(date) {
    const pad = value => String(value).padStart(2, '0');
    return 'wcli_' + date.getUTCFullYear()
      + pad(date.getUTCMonth() + 1)
      + pad(date.getUTCDate())
      + pad(date.getUTCHours())
      + pad(date.getUTCMinutes())
      + pad(date.getUTCSeconds())
      + '_' + _randomHex(6);
  }

  async function _writeChatMessage(provider, sourceFolder, roomPath, from, text, now) {
    const roomDir = _roomDir(roomPath, sourceFolder);
    await _directoryHandle(provider, roomDir, true);
    const filePath = _joinPath(roomDir, _messageFileName(now));
    await provider.writeText(filePath, _messageMarkdown(roomPath, from, text, now.toISOString()));
  }

  handlers.push(async function _dropboxWorkspaceCliHandler({ method, body, url, pathname }) {
    if (!/^\/workspace-cli(\/|$)/.test(pathname)) return NOT_HANDLED;
    if (pathname !== '/workspace-cli/request' || method !== 'POST') {
      throw new Error('クラウドモードでは管理者PCの中継設定は変更できません');
    }
    const provider = await _requirePwaProvider('readwrite');
    const user = _currentUser(url, body || {});
    const sourceFolder = _requestSourceFolder(url, body || {});
    const roomPath = await _assertRoomAccess(provider, body?.room || 'general', user, sourceFolder);
    const text = String(body?.text || '').trim();
    if (!text) throw new Error('依頼内容を入力してください');
    const providerKey = String(body?.provider || 'codex').trim();
    if (!PROVIDER_LABELS[providerKey]) throw new Error('未対応のCLIです');
    const requesterRole = _currentWorkspaceCliRole(sourceFolder);
    const readOnly = !_isAdminRole(requesterRole);
    if (readOnly && providerKey !== 'codex') {
      throw new Error('管理者以外は読み取り専用で実行できるCodex CLIだけ利用できます');
    }
    const now = new Date();
    const requestId = _requestId(now);
    const requestPath = _joinPath(sourceFolder, REQUEST_DIR, requestId + '.json');
    await _directoryHandle(provider, _joinPath(sourceFolder, REQUEST_DIR), true);
    const payload = {
      type: 'workspace-cli-request',
      version: 1,
      id: requestId,
      status: 'pending',
      requested_at: now.toISOString(),
      workspace_id: String(body?.workspace_id || body?.workspaceId || ''),
      source_folder: sourceFolder,
      room: roomPath,
      provider: providerKey,
      provider_label: PROVIDER_LABELS[providerKey],
      from: user,
      requester_role: requesterRole || 'member',
      read_only: readOnly,
      text,
    };
    await provider.writeText(requestPath, JSON.stringify(payload, null, 2));
    await _writeChatMessage(
      provider,
      sourceFolder,
      roomPath,
      user,
      `CLIへ依頼しました（${PROVIDER_LABELS[providerKey]}）。\n管理者PCが起動中で、中継設定が有効な場合、このルームに返答されます。${readOnly ? '\n管理者以外の依頼は読み取り専用で処理されます。' : ''}\n\n${text}`,
      now,
    );
    return { ok: true, request_id: requestId, status: 'pending', room: roomPath };
  });
})();

(function () {
  const PROVIDERS = [
    { key: 'codex', label: 'Codex CLI' },
    { key: 'claude_code', label: 'Claude Code' },
    { key: 'antigravity_cli', label: 'Antigravity CLI' },
  ];
  const ADMIN_ROLES = new Set(['owner', 'admin']);

  function _htmlEsc(value) {
    if (typeof esc === 'function') return esc(value);
    return String(value ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  }

  function _icon(name, size) {
    return typeof lucide === 'function' ? lucide(name, size || 14) : '';
  }

  function _isAdminRole(role) {
    return ADMIN_ROLES.has(String(role || '').trim().toLowerCase());
  }

  function _chatSourceFolderForRole() {
    try {
      if (typeof _chatSourceFolderValue === 'function') return _chatSourceFolderValue() || '';
    } catch {}
    return '';
  }

  function _currentWorkspaceCliRole() {
    const sourceFolder = _chatSourceFolderForRole();
    try {
      if (typeof getMyRoleForPath === 'function') return String(getMyRoleForPath(sourceFolder || '') || '').trim().toLowerCase();
    } catch {}
    try {
      if (typeof _myTeamRole !== 'undefined') return String(_myTeamRole || '').trim().toLowerCase();
    } catch {}
    return '';
  }

  function _providersForCurrentRole() {
    return _isAdminRole(_currentWorkspaceCliRole()) ? PROVIDERS : PROVIDERS.filter(provider => provider.key === 'codex');
  }

  function _teamInputPayload() {
    const input = document.getElementById('team-input');
    const text = String(input?.value || '').trim();
    const atts = Array.isArray(window._teamPendingAttachments) ? window._teamPendingAttachments : (typeof _teamPendingAttachments !== 'undefined' ? _teamPendingAttachments : []);
    if (!text && atts.length === 0) return { text: '', originalText: text, attachments: [] };
    let finalText = text;
    if (atts.length > 0) {
      const imageLines = atts.map(att => {
        const alt = typeof _teamMarkdownImageAlt === 'function'
          ? _teamMarkdownImageAlt(att.name)
          : String(att.name || 'image').replace(/[\r\n]+/g, ' ').replace(/\\/g, '\\\\').replace(/\]/g, '\\]');
        return `![${alt}](/api/file-raw?path=${encodeURIComponent(att.path)})`;
      }).join('\n');
      finalText = text ? text + '\n' + imageLines : imageLines;
    }
    return { text: finalText, originalText: text, attachments: atts.slice() };
  }

  function _button() {
    return document.getElementById('team-workspace-cli-btn')
      || document.querySelector('[data-action="openWorkspaceCliRelayMenu(event)"]');
  }

  async function _sendWorkspaceCliRelayRequest(providerKey) {
    if (typeof _chatRequireSourceFolder === 'function' && !_chatRequireSourceFolder()) return false;
    if (!window._teamCurrentRoom && typeof _teamCurrentRoom === 'undefined') {
      if (typeof showStatus === 'function') showStatus('ルームを選択してください', true);
      return false;
    }
    const roomPath = typeof _teamCurrentRoom !== 'undefined' ? _teamCurrentRoom : window._teamCurrentRoom;
    if (!roomPath) {
      if (typeof showStatus === 'function') showStatus('ルームを選択してください', true);
      return false;
    }
    const input = document.getElementById('team-input');
    const payload = _teamInputPayload();
    if (!payload.text) {
      if (typeof showStatus === 'function') showStatus('依頼内容を入力してください', true);
      return false;
    }
    const sendBtn = _button();
    const inputWasDisabled = !!input?.disabled;
    const sendWasDisabled = !!sendBtn?.disabled;
    if (input) input.disabled = true;
    if (sendBtn) sendBtn.disabled = true;
    try {
      if (typeof _chatWithDraftUploadCleanupPaused === 'function') {
        _chatWithDraftUploadCleanupPaused(() => { if (input) input.value = ''; });
      } else if (input) {
        input.value = '';
      }
      if (typeof _teamPendingAttachments !== 'undefined') _teamPendingAttachments = [];
      if (typeof _autoGrowTextarea === 'function') _autoGrowTextarea(input, 2, 8);
      if (typeof _renderTeamAttachments === 'function') _renderTeamAttachments();
      const bodyBase = {
        room: roomPath,
        provider: providerKey,
        text: payload.text,
        from: typeof getUsername === 'function' ? getUsername() : 'anonymous',
      };
      const requesterRole = _currentWorkspaceCliRole();
      bodyBase.requester_role = requesterRole || 'member';
      bodyBase.read_only = !_isAdminRole(requesterRole);
      if (bodyBase.read_only && providerKey !== 'codex') {
        throw new Error('管理者以外は読み取り専用で実行できるCodex CLIだけ利用できます');
      }
      if (typeof _chatSourceFolderValue === 'function') {
        const sourceFolder = _chatSourceFolderValue();
        if (sourceFolder) bodyBase.source_folder = sourceFolder;
      }
      const body = typeof _chatPostPayload === 'function' ? _chatPostPayload(bodyBase) : bodyBase;
      const path = typeof _chatApiPath === 'function' ? _chatApiPath('/workspace-cli/request') : '/workspace-cli/request';
      await apiPost(path, body);
      if (typeof _chatCommitDraftUploadsForText === 'function') _chatCommitDraftUploadsForText('team-input', payload.originalText);
      if (typeof pollTeamMessages === 'function') await pollTeamMessages();
      if (typeof showStatus === 'function') showStatus('CLIへ依頼しました');
      return true;
    } catch (e) {
      if (input) {
        input.value = payload.originalText;
        if (typeof _autoGrowTextarea === 'function') _autoGrowTextarea(input, 2, 8);
      }
      if (typeof _teamPendingAttachments !== 'undefined') _teamPendingAttachments = payload.attachments;
      if (typeof _renderTeamAttachments === 'function') _renderTeamAttachments();
      if (typeof showStatus === 'function') showStatus('CLIへの依頼に失敗しました: ' + (e?.message || e), true);
      return false;
    } finally {
      if (input?.isConnected) input.disabled = inputWasDisabled;
      if (sendBtn?.isConnected) sendBtn.disabled = sendWasDisabled;
    }
  }

  function openWorkspaceCliRelayMenu(event) {
    event?.preventDefault?.();
    event?.stopPropagation?.();
    if (typeof _chatRequireSourceFolder === 'function' && !_chatRequireSourceFolder()) return;
    const payload = _teamInputPayload();
    if (!payload.text) {
      if (typeof showStatus === 'function') showStatus('依頼内容を入力してください', true);
      return;
    }
    document.querySelectorAll('.gb-context-menu.workspace-cli-relay-menu').forEach(el => el.remove());
    const menu = document.createElement('div');
    menu.className = 'gb-context-menu workspace-cli-relay-menu';
    menu.setAttribute('role', 'menu');
    menu.setAttribute('aria-label', 'CLI依頼先');
    menu.style.cssText = 'min-width:230px;max-width:min(320px,calc(100vw - 16px));padding:6px;';
    let closeMenu = () => menu.remove();
    const desc = document.createElement('div');
    desc.className = 'gb-section-desc';
    desc.style.cssText = 'padding:6px 8px 8px;font-size:12px;line-height:1.45;';
    const requesterRole = _currentWorkspaceCliRole();
    const isAdmin = _isAdminRole(requesterRole);
    desc.textContent = isAdmin
      ? '管理者PCが起動中で中継設定が有効な時だけ返答されます。'
      : '管理者以外の依頼はCLIで読み取り専用として処理されます。';
    menu.appendChild(desc);
    _providersForCurrentRole().forEach(provider => {
      const item = document.createElement('button');
      item.type = 'button';
      item.className = 'gb-context-menu-item';
      item.setAttribute('role', 'menuitem');
      item.setAttribute('aria-label', provider.label + 'に依頼');
      item.style.cssText = 'width:100%;display:flex;align-items:center;gap:8px;';
      item.innerHTML = _icon('terminal', 14) + '<span>' + _htmlEsc(provider.label) + 'に依頼</span>';
      item.addEventListener('click', async () => {
        closeMenu();
        await _sendWorkspaceCliRelayRequest(provider.key);
      });
      menu.appendChild(item);
    });
    document.body.appendChild(menu);
    const rect = event?.currentTarget?.getBoundingClientRect?.() || event?.target?.getBoundingClientRect?.();
    const zoom = typeof _getZoom === 'function' ? _getZoom() : 1;
    menu.style.left = ((rect ? rect.left : (event?.clientX || 24)) / zoom) + 'px';
    menu.style.top = ((rect ? rect.bottom + 4 : (event?.clientY || 24)) / zoom) + 'px';
    if (typeof clampPopupToViewport === 'function') clampPopupToViewport(menu);
    setTimeout(() => {
      const closer = (ev) => {
        if (!menu.contains(ev.target)) {
          closeMenu();
        }
      };
      const keyCloser = (ev) => {
        if (ev.key === 'Escape') closeMenu();
      };
      closeMenu = () => {
        menu.remove();
        document.removeEventListener('pointerdown', closer);
        document.removeEventListener('keydown', keyCloser, true);
      };
      document.addEventListener('pointerdown', closer);
      document.addEventListener('keydown', keyCloser, true);
      menu.querySelector('.gb-context-menu-item')?.focus?.();
    }, 0);
  }

  function _workspaceRows(config) {
    const rows = Array.isArray(config?.workspaces) ? config.workspaces : [];
    if (!rows.length) return '<div class="gb-section-desc">登録済みワークスペースがありません。</div>';
    const enabledIds = Array.isArray(config?.enabled_workspace_ids) ? config.enabled_workspace_ids : [];
    const allEnabled = enabledIds.length === 0;
    return rows.map(item => {
      const checked = allEnabled || item.enabled ? 'checked' : '';
      return `<label class="gb-check" style="display:flex;margin-top:6px;min-width:0;">
        <input type="checkbox" data-workspace-cli-workspace="${_htmlEsc(item.id)}" ${checked}>
        <span style="min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;" title="${_htmlEsc(item.folder || '')}">${_htmlEsc(item.name || item.id)}</span>
      </label>`;
    }).join('');
  }

  function _renderRelaySettings(container, config) {
    if (!container) return;
    container.innerHTML = `
      <div style="border-top:1px solid var(--border);margin-top:12px;padding-top:12px;">
        <div class="gb-check-help-row">
          <label class="gb-check">
            <input id="settings-workspace-cli-enabled" type="checkbox" ${config?.enabled ? 'checked' : ''}>
            <span>ワークスペースチャットから管理者PCのCLIへ依頼できるようにする</span>
          </label>
          ${fieldHelp('このPCが起動中の時だけ、共有ワークスペース内のCLI依頼を処理します。')}
        </div>
        <div style="display:grid;grid-template-columns:minmax(120px,1fr) 90px;gap:8px;margin-top:8px;">
          <input id="settings-workspace-cli-node-name" class="gb-input" value="${_htmlEsc(config?.node_name || '')}" placeholder="このPCの表示名">
          <input id="settings-workspace-cli-poll-interval" class="gb-input" type="number" min="2" max="3600" value="${Number(config?.poll_interval_seconds || 5)}" title="確認間隔（秒）">
        </div>
        <label class="gb-check" style="margin-top:8px;">
          <input id="settings-workspace-cli-all-workspaces" type="checkbox" ${(config?.enabled_workspace_ids || []).length ? '' : 'checked'}>
          <span>登録済みワークスペースすべてを対象にする</span>
        </label>
        <div id="settings-workspace-cli-workspaces" style="margin-top:4px;max-height:120px;overflow:auto;">${_workspaceRows(config)}</div>
        <div class="btn-row" style="justify-content:flex-start;gap:8px;margin-top:10px;flex-wrap:wrap;">
          <button type="button" class="gb-btn gb-btn-sm" id="settings-workspace-cli-refresh">${_icon('refreshCw',14)} 状態を更新</button>
          <button type="button" class="gb-btn gb-btn-sm" id="settings-workspace-cli-save">${_icon('save',14)} 中継設定を保存</button>
        </div>
        <div id="settings-workspace-cli-status" class="gb-section-desc" style="margin-top:6px;"></div>
      </div>
    `;
    container.querySelector('#settings-workspace-cli-refresh')?.addEventListener('click', () => renderWorkspaceCliRelaySettingsForSettings(container.closest('.modal-overlay') || document));
    container.querySelector('#settings-workspace-cli-save')?.addEventListener('click', () => saveWorkspaceCliRelaySettingsFromSettingsDialog(container.closest('.modal-overlay') || document));
    container.querySelector('#settings-workspace-cli-all-workspaces')?.addEventListener('change', (event) => {
      const disabled = !!event.target.checked;
      container.querySelectorAll('[data-workspace-cli-workspace]').forEach(cb => { cb.disabled = disabled; });
    });
    const allCb = container.querySelector('#settings-workspace-cli-all-workspaces');
    if (allCb?.checked) container.querySelectorAll('[data-workspace-cli-workspace]').forEach(cb => { cb.disabled = true; });
    if (typeof replaceIcons === 'function') replaceIcons(container);
  }

  async function renderWorkspaceCliRelaySettingsForSettings(root) {
    const scope = root?.querySelector ? root : document;
    const container = scope.querySelector('#settings-workspace-cli-relay-container') || document.getElementById('settings-workspace-cli-relay-container');
    if (!container) return;
    container.innerHTML = '<div class="gb-section-desc">中継設定を読み込み中...</div>';
    try {
      const config = await apiFetch('/workspace-cli/config', { silentError: true });
      _renderRelaySettings(container, config);
    } catch (e) {
      container.innerHTML = '<div class="gb-section-desc">中継設定はデスクトップ版の管理者PCで変更できます。</div>';
    }
  }

  async function saveWorkspaceCliRelaySettingsFromSettingsDialog(root, options = {}) {
    const scope = root?.querySelector ? root : document;
    const container = scope.querySelector('#settings-workspace-cli-relay-container') || document.getElementById('settings-workspace-cli-relay-container');
    if (!container || !container.querySelector('#settings-workspace-cli-enabled')) return true;
    const status = container.querySelector('#settings-workspace-cli-status');
    const allWorkspaces = container.querySelector('#settings-workspace-cli-all-workspaces')?.checked !== false;
    const enabledWorkspaceIds = allWorkspaces
      ? []
      : Array.from(container.querySelectorAll('[data-workspace-cli-workspace]'))
        .filter(cb => cb.checked)
        .map(cb => cb.dataset.workspaceCliWorkspace)
        .filter(Boolean);
    const body = {
      enabled: container.querySelector('#settings-workspace-cli-enabled')?.checked === true,
      node_name: container.querySelector('#settings-workspace-cli-node-name')?.value?.trim() || '',
      poll_interval_seconds: Number(container.querySelector('#settings-workspace-cli-poll-interval')?.value || 5) || 5,
      enabled_workspace_ids: enabledWorkspaceIds,
    };
    try {
      if (status) {
        status.textContent = '保存中...';
        status.style.color = 'var(--fg2)';
      }
      await apiPut('/workspace-cli/config', body);
      if (status) {
        status.textContent = '保存しました。このPCが起動中の時に依頼を処理します。';
        status.style.color = 'var(--fg2)';
      }
      if (!options.skipReload) await renderWorkspaceCliRelaySettingsForSettings(container.closest('.modal-overlay') || document);
      if (!options.silent && typeof showStatus === 'function') showStatus('中継設定を保存しました');
      return true;
    } catch (e) {
      if (status) {
        status.textContent = '保存に失敗しました: ' + (e?.message || e);
        status.style.color = 'var(--red)';
      }
      if (!options.silent && typeof showStatus === 'function') showStatus('中継設定の保存に失敗しました', true);
      return false;
    }
  }

  window.openWorkspaceCliRelayMenu = openWorkspaceCliRelayMenu;
  window.sendWorkspaceCliRelayRequest = _sendWorkspaceCliRelayRequest;
  window.renderWorkspaceCliRelaySettingsForSettings = renderWorkspaceCliRelaySettingsForSettings;
  window.saveWorkspaceCliRelaySettingsFromSettingsDialog = saveWorkspaceCliRelaySettingsFromSettingsDialog;
})();

;

/* === gb-cal-oauth-browser.js === */
;
/* ==============================
   gb-cal-oauth-browser.js: ブラウザ完結OAuth（PKCE）共通フロー

   Cloud外部カレンダー連携 Phase 5・案A（app/docs/production-management-ux-improvement-plan-2026-08-04.md §6.5）。
   Google Calendar / Microsoft Calendar の認可コード+PKCEフローを、サーバー無し
   （静的ホスティング）でブラウザだけで完結させるための共通土台。

   役割:
   - PKCE の code_verifier / code_challenge 生成（gb-dropbox-auth.js の
     _randomToken / _sha256Base64Url と同じ方式。Web Cryptoのみに依存し、
     フォールバック実装は持たない — gb-llm-keys-store.js と同じ方針）
   - ポップアップを開いて oauth-callback.html からの通知（postMessage /
     BroadcastChannel の両方）を待つ共通フロー
   - state の照合（CSRF対策。フラグメント/クエリどちら経由でもここで必ず検証する）
   - Google / Microsoft のトークンエンドポイントへの交換・更新リクエスト
     （呼び出し元 gb-cal-cloud-sync.js が実際のフィールドマッピング・保存を担当）

   このファイルは秘密情報をログ出力しない。トークンをURLへ載せない
   （認可コードはpostMessage/BroadcastChannel経由のみで受け渡す）。
   ============================== */
(function () {
  'use strict';

  const CALLBACK_CHANNEL_NAME = 'meldex-cal-oauth-callback-v1';
  const CALLBACK_MESSAGE_TYPE = 'meldex-cal-oauth-callback';
  const DEFAULT_TIMEOUT_MS = 5 * 60 * 1000;
  const POPUP_POLL_MS = 500;

  function _webCrypto() {
    const api = globalThis.crypto;
    if (!api?.subtle || !api?.getRandomValues) throw new Error('このブラウザではWeb Cryptoを利用できないため、OAuth認証を実行できません');
    return api;
  }

  function _base64UrlBytes(bytes) {
    let raw = '';
    new Uint8Array(bytes || []).forEach((value) => { raw += String.fromCharCode(value); });
    const b64 = (typeof btoa === 'function' ? btoa(raw) : Buffer.from(raw, 'binary').toString('base64'));
    return b64.replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/g, '');
  }

  function randomToken(byteLength) {
    const bytes = new Uint8Array(byteLength || 32);
    _webCrypto().getRandomValues(bytes);
    return _base64UrlBytes(bytes);
  }

  async function sha256Base64Url(text) {
    const data = new TextEncoder().encode(String(text || ''));
    const digest = await _webCrypto().subtle.digest('SHA-256', data);
    return _base64UrlBytes(new Uint8Array(digest));
  }

  // --- PKCE ------------------------------------------------------------

  async function generatePkce() {
    const verifier = randomToken(48);
    const challenge = await sha256Base64Url(verifier);
    return { verifier, challenge, method: 'S256' };
  }

  function generateState() {
    return randomToken(24);
  }

  function redirectUri() {
    // <現在のorigin>/oauth-callback.html。サブパス配信（例: /app/）でも
    // 相対解決できるよう現在のスクリプトの場所ではなく document.baseURI を基準にする。
    try {
      return new URL('oauth-callback.html', document.baseURI || window.location.href).href;
    } catch {
      return window.location.origin + '/oauth-callback.html';
    }
  }

  // --- ポップアップ + コールバック待受 -------------------------------------

  function openBlankPopup(label) {
    // ポップアップブロッカー回避のため、URLが決まる前（PKCE生成やAPI呼び出しの前）に
    // クリックハンドラから同期的に呼び出すことを想定した「空ポップアップを先に開く」関数。
    const popup = window.open('', 'meldex-cal-oauth', 'width=520,height=680,noopener=no,noreferrer=no');
    if (!popup) {
      throw new Error(`ポップアップがブロックされました。ブラウザの設定で${label || 'このサイト'}のポップアップを許可してください`);
    }
    try {
      popup.document.title = 'Meldex 認証';
      popup.document.body.innerHTML = '<p style="font-family:sans-serif;color:#888;text-align:center;margin-top:40vh;">読み込み中…</p>';
    } catch {}
    return popup;
  }

  function navigatePopup(popup, url) {
    if (!popup || popup.closed) throw new Error('認証用ウィンドウが閉じられました');
    popup.location.href = url;
  }

  function awaitCallback(popup, expectedState, options = {}) {
    const timeoutMs = Number(options.timeoutMs) > 0 ? Number(options.timeoutMs) : DEFAULT_TIMEOUT_MS;
    return new Promise((resolve, reject) => {
      let settled = false;
      let channel = null;
      let pollTimer = 0;
      let timeoutTimer = 0;

      const cleanup = () => {
        if (settled) return;
        settled = true;
        window.removeEventListener('message', onMessage);
        try { channel?.close(); } catch {}
        if (pollTimer) clearInterval(pollTimer);
        if (timeoutTimer) clearTimeout(timeoutTimer);
      };

      const finish = (err, payload) => {
        if (settled) return;
        cleanup();
        try { if (popup && !popup.closed) popup.close(); } catch {}
        if (err) reject(err);
        else resolve(payload);
      };

      const handlePayload = (payload) => {
        if (!payload || typeof payload !== 'object') return;
        if (payload.error) {
          finish(new Error(payload.errorDescription || payload.error_description || payload.error));
          return;
        }
        if (!payload.code) return;
        if (String(payload.state || '') !== String(expectedState || '')) {
          finish(new Error('認証の状態確認(state)が一致しませんでした。もう一度お試しください'));
          return;
        }
        finish(null, { code: payload.code, state: payload.state });
      };

      const onMessage = (event) => {
        if (event.origin !== window.location.origin) return;
        const data = event.data;
        if (!data || data.type !== CALLBACK_MESSAGE_TYPE) return;
        handlePayload(data.payload);
      };
      window.addEventListener('message', onMessage);

      try {
        if (typeof BroadcastChannel === 'function') {
          channel = new BroadcastChannel(CALLBACK_CHANNEL_NAME);
          channel.addEventListener('message', (event) => {
            const data = event?.data;
            if (!data || data.type !== CALLBACK_MESSAGE_TYPE) return;
            handlePayload(data.payload);
          });
        }
      } catch {
        channel = null;
      }

      // ユーザーがポップアップを閉じた場合の検知（コールバックが届かないまま放置しない）。
      pollTimer = setInterval(() => {
        if (popup && popup.closed) finish(new Error('認証がキャンセルされました（ウィンドウが閉じられました）'));
      }, POPUP_POLL_MS);

      timeoutTimer = setTimeout(() => {
        finish(new Error('認証の待機時間が切れました。もう一度お試しください'));
      }, timeoutMs);
    });
  }

  // --- Google ------------------------------------------------------------

  const GOOGLE_AUTH_ENDPOINT = 'https://accounts.google.com/o/oauth2/v2/auth';
  const GOOGLE_TOKEN_ENDPOINT = 'https://oauth2.googleapis.com/token';
  const GOOGLE_CALENDAR_SCOPE = 'https://www.googleapis.com/auth/calendar';

  function buildGoogleAuthUrl({ clientId, redirectUri: uri, state, challenge, scope }) {
    const params = new URLSearchParams({
      client_id: clientId,
      redirect_uri: uri,
      response_type: 'code',
      scope: scope || GOOGLE_CALENDAR_SCOPE,
      access_type: 'offline',
      prompt: 'consent',
      state,
      code_challenge: challenge,
      code_challenge_method: 'S256',
    });
    return GOOGLE_AUTH_ENDPOINT + '?' + params.toString();
  }

  async function _postForm(url, data) {
    const response = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: new URLSearchParams(data).toString(),
    });
    let payload = null;
    try { payload = await response.json(); } catch { payload = null; }
    if (!response.ok) {
      const message = payload?.error_description || payload?.error || `HTTP ${response.status}`;
      const error = new Error(message);
      error.status = response.status;
      error.code = payload?.error || '';
      throw error;
    }
    return payload || {};
  }

  async function exchangeGoogleToken({ code, verifier, clientId, clientSecret, redirectUri: uri }) {
    return _postForm(GOOGLE_TOKEN_ENDPOINT, {
      code,
      client_id: clientId,
      client_secret: clientSecret,
      redirect_uri: uri,
      grant_type: 'authorization_code',
      code_verifier: verifier,
    });
  }

  async function refreshGoogleToken({ refreshToken, clientId, clientSecret }) {
    return _postForm(GOOGLE_TOKEN_ENDPOINT, {
      refresh_token: refreshToken,
      client_id: clientId,
      client_secret: clientSecret,
      grant_type: 'refresh_token',
    });
  }

  async function authorizeGoogle({ clientId, clientSecret, scope, popup, timeoutMs }) {
    if (!clientId || !clientSecret) throw new Error('Client IDとClient Secretを入力してください');
    const win = popup || openBlankPopup('Google');
    const { verifier, challenge } = await generatePkce();
    const state = generateState();
    const uri = redirectUri();
    const authUrl = buildGoogleAuthUrl({ clientId, redirectUri: uri, state, challenge, scope });
    navigatePopup(win, authUrl);
    const { code } = await awaitCallback(win, state, { timeoutMs });
    const token = await exchangeGoogleToken({ code, verifier, clientId, clientSecret, redirectUri: uri });
    return { token, clientId, clientSecret };
  }

  // --- Microsoft (SPA / PKCE。クライアントシークレット不要) ------------------

  function microsoftAuthEndpoint(tenant) {
    return `https://login.microsoftonline.com/${encodeURIComponent(tenant || 'common')}/oauth2/v2.0/authorize`;
  }

  function microsoftTokenEndpoint(tenant) {
    return `https://login.microsoftonline.com/${encodeURIComponent(tenant || 'common')}/oauth2/v2.0/token`;
  }

  const MICROSOFT_CALENDAR_SCOPE = 'offline_access User.Read Calendars.ReadWrite';

  function buildMicrosoftAuthUrl({ clientId, tenant, redirectUri: uri, state, challenge, scope }) {
    const params = new URLSearchParams({
      client_id: clientId,
      redirect_uri: uri,
      response_type: 'code',
      response_mode: 'query',
      scope: scope || MICROSOFT_CALENDAR_SCOPE,
      state,
      code_challenge: challenge,
      code_challenge_method: 'S256',
    });
    return microsoftAuthEndpoint(tenant) + '?' + params.toString();
  }

  async function exchangeMicrosoftToken({ code, verifier, clientId, tenant, redirectUri: uri, scope }) {
    return _postForm(microsoftTokenEndpoint(tenant), {
      code,
      client_id: clientId,
      redirect_uri: uri,
      grant_type: 'authorization_code',
      code_verifier: verifier,
      scope: scope || MICROSOFT_CALENDAR_SCOPE,
    });
  }

  async function refreshMicrosoftToken({ refreshToken, clientId, tenant, scope }) {
    return _postForm(microsoftTokenEndpoint(tenant), {
      refresh_token: refreshToken,
      client_id: clientId,
      grant_type: 'refresh_token',
      scope: scope || MICROSOFT_CALENDAR_SCOPE,
    });
  }

  async function authorizeMicrosoft({ clientId, tenant, scope, popup, timeoutMs }) {
    if (!clientId) throw new Error('Application (client) IDを入力してください');
    const win = popup || openBlankPopup('Microsoft');
    const { verifier, challenge } = await generatePkce();
    const state = generateState();
    const uri = redirectUri();
    const authUrl = buildMicrosoftAuthUrl({ clientId, tenant, redirectUri: uri, state, challenge, scope });
    navigatePopup(win, authUrl);
    const { code } = await awaitCallback(win, state, { timeoutMs });
    const token = await exchangeMicrosoftToken({ code, verifier, clientId, tenant, redirectUri: uri, scope });
    return { token, clientId, tenant: tenant || 'common' };
  }

  window.MeldexCalOAuthBrowser = {
    CALLBACK_CHANNEL_NAME,
    CALLBACK_MESSAGE_TYPE,
    generatePkce,
    generateState,
    redirectUri,
    randomToken,
    sha256Base64Url,
    openBlankPopup,
    navigatePopup,
    awaitCallback,
    google: {
      SCOPE: GOOGLE_CALENDAR_SCOPE,
      buildAuthUrl: buildGoogleAuthUrl,
      exchangeToken: exchangeGoogleToken,
      refreshToken: refreshGoogleToken,
      authorize: authorizeGoogle,
    },
    microsoft: {
      SCOPE: MICROSOFT_CALENDAR_SCOPE,
      buildAuthUrl: buildMicrosoftAuthUrl,
      exchangeToken: exchangeMicrosoftToken,
      refreshToken: refreshMicrosoftToken,
      authorize: authorizeMicrosoft,
    },
  };
})();

;

/* === gb-cal-oauth-store.js === */
;
/* ==============================
   gb-cal-oauth-store.js: カレンダー外部連携（Google/Microsoft）OAuth認証情報の
   端末ローカル保護保存（Cloud=Dropboxブラウザ完結版専用）

   コミット前レビュー指摘 #10（production-management-ux-improvement-plan-2026-08-04.md）:
   gb-cal-cloud-sync.js / gb-cal-cloud-tasks.js は client_secret・refresh_token・
   access_token を接続中のDropboxワークスペース内 `_calendar/*.json` へ平文で保存して
   いた。共有フォルダの他メンバーやDropboxのバージョン履歴経由で読める状態は保護水準が
   低いため、gb-llm-keys-store.js の「local-device」モード（IndexedDB。既定・パスフレーズ
   不要で自動同期の裏側から使える）と同じ仕組み・同じ保護水準（ブラウザのIndexedDBは
   オリジン限定でDropbox同期の対象外）へ変更する。

   既存プレーンテキストからの読み替え互換: 呼び出し側（gb-cal-cloud-sync.js /
   gb-cal-cloud-tasks.js の _readAuth）が、旧位置（Dropbox JSON）に平文の秘密フィールドを
   見つけたら、この store へ一度だけ移してから旧位置の平文フィールドを削除する
   （extractSecretFields / stripSecretFields を使う）。

   ファイル名注記（2026-08-05）: 元は gb-cal-oauth-token-store.js だったが、Cloud静的ビルド
   検証（build_cloud_static_manifest.FORBIDDEN_NAME_RE）が区切り語「token」を含むファイル名を
   配布物から機械的に拒否するため、現在の名前へ改名した（実体は変更なし。禁止パターン自体は
   実秘密ファイル混入を防ぐガードのため緩和しない）。

   LLM APIキー保存とは別のIndexedDBデータベースにする（用途が異なり、削除・エクスポート等の
   ライフサイクルを混在させたくないため）。トークンをログへ出力しないこと。
   ============================== */
(function () {
  'use strict';

  const DB_NAME = 'meldex-cal-oauth-tokens';
  const STORE_NAME = 'tokens';
  const DB_VERSION = 1;
  // client_id・tenant・sync_state・connected用途のexpires_at等は秘匿の必要が薄い接続
  // メタデータなので対象外（Dropbox側に残し、複数端末での「接続状態」表示・差分同期の
  // 継続に使う）。悪用されると即座にアカウントへアクセスできる3つだけを保護する。
  const SECRET_FIELDS = Object.freeze(['client_secret', 'access_token', 'refresh_token']);

  let _dbPromise = null;

  function _openDb() {
    if (_dbPromise) return _dbPromise;
    _dbPromise = new Promise((resolve, reject) => {
      if (!window.indexedDB) {
        reject(new Error('IndexedDB is not available'));
        return;
      }
      const req = indexedDB.open(DB_NAME, DB_VERSION);
      req.onupgradeneeded = () => {
        const db = req.result;
        if (!db.objectStoreNames.contains(STORE_NAME)) db.createObjectStore(STORE_NAME, { keyPath: 'key' });
      };
      req.onsuccess = () => resolve(req.result);
      req.onerror = () => reject(req.error || new Error('IndexedDB open failed'));
      req.onblocked = () => reject(new Error('IndexedDB open blocked'));
    });
    return _dbPromise;
  }

  async function getSecrets(key) {
    if (!key) return null;
    try {
      const db = await _openDb();
      return await new Promise((resolve, reject) => {
        const req = db.transaction(STORE_NAME, 'readonly').objectStore(STORE_NAME).get(key);
        req.onsuccess = () => resolve(req.result?.value || null);
        req.onerror = () => reject(req.error || new Error('IndexedDB read failed'));
      });
    } catch {
      return null;
    }
  }

  async function setSecrets(key, value) {
    if (!key) return { ok: false };
    const db = await _openDb();
    await new Promise((resolve, reject) => {
      const tx = db.transaction(STORE_NAME, 'readwrite');
      tx.objectStore(STORE_NAME).put({ key, value: value && typeof value === 'object' ? value : {}, updatedAt: new Date().toISOString() });
      tx.oncomplete = () => resolve();
      tx.onerror = () => reject(tx.error || new Error('IndexedDB write failed'));
      tx.onabort = () => reject(tx.error || new Error('IndexedDB write aborted'));
    });
    return { ok: true };
  }

  async function deleteSecrets(key) {
    if (!key) return { ok: true };
    try {
      const db = await _openDb();
      await new Promise((resolve, reject) => {
        const req = db.transaction(STORE_NAME, 'readwrite').objectStore(STORE_NAME).delete(key);
        req.onsuccess = () => resolve();
        req.onerror = () => reject(req.error || new Error('IndexedDB delete failed'));
      });
    } catch {}
    return { ok: true };
  }

  function extractSecretFields(payload) {
    const secrets = {};
    SECRET_FIELDS.forEach((field) => {
      if (payload && Object.prototype.hasOwnProperty.call(payload, field)) secrets[field] = payload[field];
    });
    return secrets;
  }

  function stripSecretFields(payload) {
    const rest = { ...(payload || {}) };
    SECRET_FIELDS.forEach((field) => { delete rest[field]; });
    return rest;
  }

  function hasAnySecretValue(secrets) {
    return !!secrets && Object.values(secrets).some((value) => String(value || '').trim() !== '');
  }

  window.MeldexCalOAuthTokenStore = {
    SECRET_FIELDS: SECRET_FIELDS.slice(),
    getSecrets,
    setSecrets,
    deleteSecrets,
    extractSecretFields,
    stripSecretFields,
    hasAnySecretValue,
  };
})();

;

/* === gb-cal-cloud-sync.js === */
;
/* ==============================
   gb-cal-cloud-sync.js: Cloud（Dropboxモード）向け Google/Microsoft Calendar 同期エンジン

   Cloud外部カレンダー連携 Phase 5・案A（app/docs/production-management-ux-improvement-plan-2026-08-04.md §6.5）。
   Desktop側 meldex_api_calendar_sync.part01.part01.py / part02.py の
   フィールドマッピング・対応付け・重複防止ロジックを仕様の正とし、ブラウザ完結
   （サーバー無し）版として同一挙動になるよう移植する。

   認証: gb-cal-oauth-browser.js のPKCE+ポップアップ共通フローを使う（Google/Microsoft
   共通）。認証状態・トークン・差分同期用の状態（syncToken/deltaLink）は、接続中の
   Dropboxワークスペース内 `_calendar/` フォルダへ保存する（gb-data-access-dropbox-expanded
   の calendar store と同じ置き場。ワークスペース単位で保存されリロード後も維持される）。

   このファイルは __MeldexPwaDataAccessExtensions ハンドラとして
   `/cal/sync/status` `/cal/sync/google/pull` `/cal/sync/google/push`
   `/cal/sync/microsoft/pull` `/cal/sync/microsoft/push` を横取りする。
   Meldex.html 側で gb-data-access-dropbox-expanded.js より前に読み込むことで、
   同ファイルの「Cloud BETAでは無効です」catch-all より先にこのハンドラが応答する
   （gb-staff-registry-cloud-twin.js と同じ配線パターン。
   gb-data-access-dropbox-expanded.part01.js / part02.js は他レーンの成果があるため
   直接編集しない）。

   認証コード交換・トークン更新（`/cal/sync/google/auth` 等）はこのハンドラでは
   扱わない。ポップアップはユーザー操作（クリック）から同期的に開く必要があるため、
   gb-tool-calendar-sync.js のCloud専用ボタン処理が window.MeldexCalCloudSync の
   authorizeGoogle/authorizeMicrosoft を直接呼び出す（fetch経由の非同期チェーンを
   挟むとポップアップブロッカーに阻まれるリスクがあるため）。

   秘密情報はログ出力しない。トークンをURLへ載せない。
   ============================== */
(function () {
  'use strict';

  const internals = window.__MeldexPwaDataAccessInternals;
  const handlers = window.__MeldexPwaDataAccessExtensions;
  if (!internals || !Array.isArray(handlers)) return;

  const { NOT_HANDLED, _joinPath, _requirePwaProvider, _directoryHandle, _readJsonSafe } = internals;

  const CAL_DIR = '_calendar';
  const EVENTS_PATH = _joinPath(CAL_DIR, 'events.json');
  const GOOGLE_AUTH_PATH = _joinPath(CAL_DIR, 'google_calendar_auth.json');
  const MICROSOFT_AUTH_PATH = _joinPath(CAL_DIR, 'microsoft_calendar_auth.json');
  const TOKEN_EARLY_REFRESH_MS = 60 * 1000;

  function _oauth() {
    const api = window.MeldexCalOAuthBrowser;
    if (!api) throw new Error('gb-cal-oauth-browser.js が読み込まれていません');
    return api;
  }

  function _httpError(message, status, code) {
    const err = new Error(message);
    err.status = status || 500;
    if (code) err.code = code;
    return err;
  }

  function _randomId(prefix) {
    const rand = (globalThis.crypto?.randomUUID?.() || String(Math.random()).slice(2)) + Date.now().toString(36);
    return `${prefix || 'ev'}-${rand}`;
  }

  function _nowIso() {
    return new Date().toISOString();
  }

  // ============================================================
  // ストレージ（_calendar/ 配下のJSON。既存の calendar store と同じ置き場）
  // ============================================================

  // コミット前レビュー指摘 #10: client_secret・access_token・refresh_token は
  // gb-cal-oauth-store.js（IndexedDB。gb-llm-keys-store.js の local-device モードと
  // 同じ保護水準）へ保存し、Dropbox上の平文JSONには残さない。client_id・tenant・
  // sync_state 等の非秘匿な接続メタデータだけを従来どおりDropbox JSONへ置く（複数端末での
  // 接続状態表示・差分同期の継続に必要なため）。
  function _tokenKeyForPath(path) {
    if (path === GOOGLE_AUTH_PATH) return 'google';
    if (path === MICROSOFT_AUTH_PATH) return 'microsoft';
    return 'cal-cloud-sync:' + String(path || '');
  }

  async function _readAuth(provider, path) {
    const stored = (await _readJsonSafe(provider, path, null)) || null;
    const store = window.MeldexCalOAuthTokenStore;
    if (!store) return stored; // トークンストア未読込時は安全側フォールバックとして旧挙動を維持
    const tokenKey = _tokenKeyForPath(path);
    let secrets = await store.getSecrets(tokenKey).catch(() => null);
    if (!secrets) {
      // 読み替え互換: 旧位置（Dropbox平文JSON）に秘密フィールドが残っていれば、
      // 新位置（IndexedDB）へ一度だけ移してから旧位置の平文フィールドを削除する。
      const legacySecrets = store.extractSecretFields(stored || {});
      if (store.hasAnySecretValue(legacySecrets)) {
        await store.setSecrets(tokenKey, legacySecrets).catch(() => {});
        secrets = legacySecrets;
        if (stored) {
          await _directoryHandle(provider, CAL_DIR, true);
          await provider.writeJson(path, store.stripSecretFields(stored)).catch(() => {});
        }
      }
    }
    if (!stored && !store.hasAnySecretValue(secrets)) return null;
    return { ...store.stripSecretFields(stored || {}), ...(secrets || {}) };
  }

  async function _writeAuth(provider, path, payload) {
    const store = window.MeldexCalOAuthTokenStore;
    let metadata = payload;
    if (store) {
      const tokenKey = _tokenKeyForPath(path);
      const secrets = store.extractSecretFields(payload);
      if (Object.keys(secrets).length) await store.setSecrets(tokenKey, secrets);
      metadata = store.stripSecretFields(payload);
    }
    await _directoryHandle(provider, CAL_DIR, true);
    await provider.writeJson(path, metadata);
  }

  async function _readEvents(provider) {
    const data = await _readJsonSafe(provider, EVENTS_PATH, []);
    return Array.isArray(data) ? data : [];
  }

  async function _writeEvents(provider, rows) {
    await _directoryHandle(provider, CAL_DIR, true);
    await provider.writeJson(EVENTS_PATH, Array.isArray(rows) ? rows : []);
  }

  function _findExternalRow(rows, source, externalId, user) {
    if (!externalId) return null;
    const candidates = rows.filter((row) => (
      String(row.external_id || '') === externalId
      && String(row.calendar_source || '') === source
      && (!user || row.user === user || !row.user)
    ));
    if (!candidates.length) return null;
    return candidates.find((row) => row.user === user) || candidates[0];
  }

  function _isLocalUnsent(row, user) {
    if (row.external_id) return false;
    if (row.calendar_source && row.calendar_source !== 'local') return false;
    return !user || row.user === user;
  }

  // ============================================================
  // 日時・全日イベントの変換（Desktop側 _google_all_day_end_to_local /
  // _local_all_day_end_to_google と同じ意味論。VEVENTのDTENDは排他的終了日のため、
  // Meldex内部の「最終日を含む終了日」表現との間で相互変換する）
  // ============================================================

  function _dateOnly(value) {
    return String(value || '').slice(0, 10);
  }

  function _addDaysToDateStr(dateStr, days) {
    const parts = _dateOnly(dateStr).split('-').map(Number);
    if (parts.length !== 3 || parts.some((n) => Number.isNaN(n))) return dateStr;
    const utc = new Date(Date.UTC(parts[0], parts[1] - 1, parts[2]));
    utc.setUTCDate(utc.getUTCDate() + days);
    return utc.toISOString().slice(0, 10);
  }

  function _googleAllDayEndToLocal(startIso, endIso) {
    if (!endIso) return startIso;
    const startDay = _dateOnly(startIso);
    const endDay = _dateOnly(endIso);
    if (endDay > startDay) return _addDaysToDateStr(endDay, -1);
    return endIso;
  }

  function _localAllDayEndToGoogle(startIso, endIso) {
    const base = endIso || startIso;
    const startDay = _dateOnly(startIso);
    let endDay = _dateOnly(base);
    if (endDay < startDay) endDay = startDay;
    return _addDaysToDateStr(endDay, 1);
  }

  function _withSeconds(value) {
    // UI保存値は分精度（YYYY-MM-DDTHH:MM）のことがあるため、RFC3339が要求する秒を補う
    const text = String(value || '');
    return text.length === 16 ? text + ':00' : text;
  }

  // ============================================================
  // Google Calendar
  // ============================================================

  const GOOGLE_API_BASE = 'https://www.googleapis.com/calendar/v3';

  async function _googleAccessToken(provider) {
    const auth = await _readAuth(provider, GOOGLE_AUTH_PATH);
    if (!auth?.refresh_token) throw _httpError('Google Calendar未接続', 400, 'not_connected');
    if (auth.access_token && Number(auth.expires_at || 0) > Date.now() + TOKEN_EARLY_REFRESH_MS) return auth;
    try {
      const refreshed = await _oauth().google.refreshToken({
        refreshToken: auth.refresh_token, clientId: auth.client_id, clientSecret: auth.client_secret,
      });
      const next = {
        ...auth,
        access_token: refreshed.access_token,
        expires_at: Date.now() + Math.max(60, Number(refreshed.expires_in || 3600)) * 1000,
        refresh_token: refreshed.refresh_token || auth.refresh_token,
      };
      await _writeAuth(provider, GOOGLE_AUTH_PATH, next);
      return next;
    } catch {
      // refresh_tokenごと失効している（取り消し・期限切れ）ため、次回 /cal/sync/status で
      // connected:false に戻し、同期モーダルにログインフォームが再表示されるようにする
      // （再認証導線。access_token/refresh_tokenのみ破棄しclient_id/secretは残して手間を減らす）。
      await _writeAuth(provider, GOOGLE_AUTH_PATH, { ...auth, access_token: '', refresh_token: '', expires_at: 0 }).catch(() => {});
      throw _httpError('Googleの認証が失効しました。もう一度ログインしてください', 400, 'reauth_required');
    }
  }

  async function _googleEventsPage(accessToken, query, pageToken) {
    const url = new URL(GOOGLE_API_BASE + '/calendars/primary/events');
    Object.entries(query || {}).forEach(([key, value]) => { if (value != null) url.searchParams.set(key, value); });
    if (pageToken) url.searchParams.set('pageToken', pageToken);
    const response = await fetch(url.toString(), { headers: { Authorization: 'Bearer ' + accessToken } });
    if (response.status === 410) return { items: [], nextPageToken: '', nextSyncToken: '', expired: true };
    if (!response.ok) {
      const detail = await response.json().catch(() => null);
      throw _httpError(detail?.error?.message || `Google APIエラー(${response.status})`, response.status);
    }
    const data = await response.json();
    return { items: data.items || [], nextPageToken: data.nextPageToken || '', nextSyncToken: data.nextSyncToken || '', expired: false };
  }

  async function _googleEventsAll(accessToken, query) {
    const events = [];
    let pageToken = '';
    let nextSyncToken = '';
    for (;;) {
      const page = await _googleEventsPage(accessToken, query, pageToken);
      if (page.expired) return { events: [], nextSyncToken: '', expired: true };
      events.push(...page.items);
      nextSyncToken = page.nextSyncToken || nextSyncToken;
      pageToken = page.nextPageToken;
      if (!pageToken) return { events, nextSyncToken, expired: false };
    }
  }

  function _applyGoogleEvent(rows, ev, user, now) {
    const extId = ev.id || '';
    if (!extId) return 'skipped';
    const start = ev.start?.dateTime || ev.start?.date || '';
    const end = ev.end?.dateTime || ev.end?.date || '';
    const allDay = !!ev.start?.date;
    const endValue = allDay ? _googleAllDayEndToLocal(start, end) : end;
    const existing = _findExternalRow(rows, 'google', extId, user);
    if (existing) {
      Object.assign(existing, {
        title: ev.summary || '', start, end: endValue, all_day: allDay,
        description: ev.description || '', location: ev.location || '',
        user: existing.user || user || 'anonymous', creator: existing.creator || user || 'anonymous',
        modified: now,
      });
      return 'updated';
    }
    rows.push({
      id: _randomId('gcal'), title: ev.summary || '', start, end: endValue, all_day: allDay,
      description: ev.description || '', location: ev.location || '',
      external_id: extId, calendar_source: 'google',
      user: user || 'anonymous', creator: user || 'anonymous', members: [],
      created: now, modified: now,
    });
    return 'imported';
  }

  function _applyGoogleCancellation(rows, ev, user) {
    const extId = ev.id || '';
    if (!extId) return rows;
    const existing = _findExternalRow(rows, 'google', extId, user);
    if (!existing) return rows;
    return rows.filter((row) => row !== existing);
  }

  async function _googlePullFull(provider, user) {
    const auth = await _googleAccessToken(provider);
    const timeMin = new Date(Date.now() - 30 * 86400000).toISOString();
    const timeMax = new Date(Date.now() + 90 * 86400000).toISOString();
    const { events } = await _googleEventsAll(auth.access_token, {
      timeMin, timeMax, maxResults: 250, singleEvents: true, orderBy: 'startTime',
    });
    const rows = await _readEvents(provider);
    const now = _nowIso();
    let imported = 0; let updated = 0;
    events.forEach((ev) => {
      const action = _applyGoogleEvent(rows, ev, user, now);
      if (action === 'imported') imported += 1; else if (action === 'updated') updated += 1;
    });
    await _writeEvents(provider, rows);
    return { ok: true, imported, updated, total: events.length };
  }

  async function _googlePullIncremental(provider, user) {
    const auth = await _googleAccessToken(provider);
    const state = auth.sync_state || {};
    let { events, nextSyncToken, expired } = await _googleEventsAll(auth.access_token, {
      maxResults: 250, singleEvents: true, syncToken: state.sync_token || undefined, showDeleted: state.sync_token ? true : undefined,
    });
    let fallbackFull = false;
    if (expired) {
      fallbackFull = true;
      ({ events, nextSyncToken } = await _googleEventsAll(auth.access_token, { maxResults: 250, singleEvents: true }));
    }
    const rows = await _readEvents(provider);
    const now = _nowIso();
    let imported = 0; let updated = 0; let deleted = 0;
    let current = rows;
    events.forEach((ev) => {
      if (ev.status === 'cancelled') {
        const before = current.length;
        current = _applyGoogleCancellation(current, ev, user);
        if (current.length < before) deleted += 1;
      } else {
        const action = _applyGoogleEvent(current, ev, user, now);
        if (action === 'imported') imported += 1; else if (action === 'updated') updated += 1;
      }
    });
    await _writeEvents(provider, current);
    if (nextSyncToken) {
      await _writeAuth(provider, GOOGLE_AUTH_PATH, { ...auth, sync_state: { sync_token: nextSyncToken, updated_at: now } });
    }
    return { ok: true, imported, updated, deleted, total: events.length, incremental: true, fallback_full: fallbackFull };
  }

  async function _googlePull(provider, body) {
    const user = String(body?.user || '').trim();
    if (body?.incremental) return _googlePullIncremental(provider, user);
    return _googlePullFull(provider, user);
  }

  async function _googlePush(provider, body) {
    const user = String(body?.user || '').trim();
    const auth = await _googleAccessToken(provider);
    const rows = await _readEvents(provider);
    let pushed = 0;
    const errors = [];
    const now = _nowIso();
    for (const row of rows) {
      if (!_isLocalUnsent(row, user)) continue;
      try {
        const eventBody = { summary: row.title || '', description: row.description || '', location: row.location || '' };
        if (row.all_day) {
          eventBody.start = { date: _dateOnly(row.start) };
          eventBody.end = { date: _localAllDayEndToGoogle(row.start, row.end || row.start) };
        } else {
          eventBody.start = { dateTime: _withSeconds(row.start), timeZone: 'Asia/Tokyo' };
          eventBody.end = { dateTime: _withSeconds(row.end || row.start), timeZone: 'Asia/Tokyo' };
        }
        const response = await fetch(GOOGLE_API_BASE + '/calendars/primary/events', {
          method: 'POST',
          headers: { Authorization: 'Bearer ' + auth.access_token, 'Content-Type': 'application/json' },
          body: JSON.stringify(eventBody),
        });
        if (!response.ok) {
          const detail = await response.json().catch(() => null);
          throw new Error(detail?.error?.message || `HTTP ${response.status}`);
        }
        const result = await response.json();
        row.external_id = result.id;
        row.calendar_source = 'google';
        row.modified = now;
        pushed += 1;
      } catch (err) {
        errors.push({ id: row.id, title: row.title, error: err?.message || String(err) });
      }
    }
    await _writeEvents(provider, rows);
    return { ok: !errors.length, pushed, failed: errors.length, errors };
  }

  // ============================================================
  // Microsoft Calendar（Graph API）
  // ============================================================

  const GRAPH_BASE = 'https://graph.microsoft.com/v1.0';

  async function _microsoftAccessToken(provider) {
    const auth = await _readAuth(provider, MICROSOFT_AUTH_PATH);
    if (!auth?.refresh_token) throw _httpError('Microsoft Calendar未接続', 400, 'not_connected');
    if (auth.access_token && Number(auth.expires_at || 0) > Date.now() + TOKEN_EARLY_REFRESH_MS) return auth;
    try {
      const refreshed = await _oauth().microsoft.refreshToken({
        refreshToken: auth.refresh_token, clientId: auth.client_id, tenant: auth.tenant,
      });
      const next = {
        ...auth,
        access_token: refreshed.access_token,
        expires_at: Date.now() + Math.max(60, Number(refreshed.expires_in || 3600)) * 1000,
        refresh_token: refreshed.refresh_token || auth.refresh_token,
      };
      await _writeAuth(provider, MICROSOFT_AUTH_PATH, next);
      return next;
    } catch {
      // Google側と同じ理由でrefresh_tokenごと破棄し、再認証導線（ログインフォーム再表示）につなげる。
      await _writeAuth(provider, MICROSOFT_AUTH_PATH, { ...auth, access_token: '', refresh_token: '', expires_at: 0 }).catch(() => {});
      throw _httpError('Microsoftの認証が失効しました。もう一度ログインしてください', 400, 'reauth_required');
    }
  }

  async function _graphJson(method, pathOrUrl, accessToken, body) {
    const url = pathOrUrl.startsWith('https://') ? pathOrUrl : GRAPH_BASE + pathOrUrl;
    const headers = { Authorization: 'Bearer ' + accessToken, Prefer: 'outlook.timezone="Asia/Tokyo", outlook.body-content-type="text"' };
    const init = { method, headers };
    if (body != null) { init.body = JSON.stringify(body); headers['Content-Type'] = 'application/json'; }
    const response = await fetch(url, init);
    if (!response.ok) {
      const detail = await response.json().catch(() => null);
      throw _httpError(detail?.error?.message || `Microsoft Graphエラー(${response.status})`, response.status);
    }
    const text = await response.text();
    return text ? JSON.parse(text) : {};
  }

  async function _graphDelta(url, accessToken) {
    const headers = { Authorization: 'Bearer ' + accessToken, Prefer: 'outlook.timezone="Asia/Tokyo", odata.track-changes' };
    const response = await fetch(url, { headers });
    if (response.status === 410) return { data: {}, expired: true };
    if (!response.ok) {
      const detail = await response.json().catch(() => null);
      throw _httpError(detail?.error?.message || `Microsoft Graphエラー(${response.status})`, response.status);
    }
    return { data: await response.json(), expired: false };
  }

  async function _microsoftDeltaEvents(accessToken, deltaLink) {
    const events = [];
    let url = deltaLink;
    if (!url) {
      const start = new Date(Date.now() - 30 * 86400000).toISOString();
      const end = new Date(Date.now() + 365 * 86400000).toISOString();
      url = `${GRAPH_BASE}/me/calendarView/delta?${new URLSearchParams({ startDateTime: start, endDateTime: end })}`;
    }
    let nextDeltaLink = '';
    while (url) {
      const { data, expired } = await _graphDelta(url, accessToken);
      if (expired) return { events: [], nextDeltaLink: '', expired: true };
      events.push(...(data.value || []));
      nextDeltaLink = data['@odata.deltaLink'] || nextDeltaLink;
      url = data['@odata.nextLink'] || '';
    }
    return { events, nextDeltaLink, expired: false };
  }

  function _mcalEventTime(info, allDay) {
    const value = info?.dateTime || '';
    if (!value) return '';
    return allDay ? value.slice(0, 10) : value.slice(0, 19);
  }

  function _applyMicrosoftEvent(rows, ev, user, now) {
    const extId = ev.id || '';
    if (!extId) return 'skipped';
    const allDay = !!ev.isAllDay;
    const start = _mcalEventTime(ev.start, allDay);
    let end = _mcalEventTime(ev.end, allDay);
    if (allDay) end = _googleAllDayEndToLocal(start, end);
    const location = ev.location?.displayName || '';
    const existing = _findExternalRow(rows, 'microsoft', extId, user);
    if (existing) {
      Object.assign(existing, {
        title: ev.subject || '', start, end, all_day: allDay,
        description: ev.body?.content || '', location, url: ev.webLink || '', color: '#0078d4',
        user: existing.user || user || 'anonymous', creator: existing.creator || user || 'anonymous',
        modified: now,
      });
      return 'updated';
    }
    rows.push({
      id: _randomId('mcal'), title: ev.subject || '', start, end, all_day: allDay,
      description: ev.body?.content || '', location, url: ev.webLink || '', color: '#0078d4',
      external_id: extId, calendar_source: 'microsoft',
      user: user || 'anonymous', creator: user || 'anonymous', members: [],
      created: now, modified: now,
    });
    return 'imported';
  }

  function _applyMicrosoftRemoval(rows, ev, user) {
    const extId = ev.id || '';
    if (!extId) return rows;
    const existing = _findExternalRow(rows, 'microsoft', extId, user);
    if (!existing) return rows;
    return rows.filter((row) => row !== existing);
  }

  async function _microsoftPullFull(provider, user) {
    const auth = await _microsoftAccessToken(provider);
    const start = new Date(Date.now() - 30 * 86400000).toISOString();
    const end = new Date(Date.now() + 90 * 86400000).toISOString();
    const query = new URLSearchParams({ startDateTime: start, endDateTime: end, $top: '500', $orderby: 'start/dateTime' });
    let url = `/me/calendar/calendarView?${query}`;
    const events = [];
    while (url) {
      const data = await _graphJson('GET', url, auth.access_token);
      events.push(...(data.value || []));
      url = data['@odata.nextLink'] || '';
    }
    const rows = await _readEvents(provider);
    const now = _nowIso();
    let imported = 0; let updated = 0;
    events.forEach((ev) => {
      const action = _applyMicrosoftEvent(rows, ev, user, now);
      if (action === 'imported') imported += 1; else if (action === 'updated') updated += 1;
    });
    await _writeEvents(provider, rows);
    return { ok: true, imported, updated, total: events.length };
  }

  async function _microsoftPullIncremental(provider, user) {
    const auth = await _microsoftAccessToken(provider);
    const state = auth.sync_state || {};
    let { events, nextDeltaLink, expired } = await _microsoftDeltaEvents(auth.access_token, state.delta_link || '');
    let fallbackFull = false;
    if (expired) {
      fallbackFull = true;
      ({ events, nextDeltaLink } = await _microsoftDeltaEvents(auth.access_token, ''));
    }
    const rows = await _readEvents(provider);
    const now = _nowIso();
    let imported = 0; let updated = 0; let deleted = 0;
    let current = rows;
    events.forEach((ev) => {
      if (ev['@removed']) {
        const before = current.length;
        current = _applyMicrosoftRemoval(current, ev, user);
        if (current.length < before) deleted += 1;
      } else {
        const action = _applyMicrosoftEvent(current, ev, user, now);
        if (action === 'imported') imported += 1; else if (action === 'updated') updated += 1;
      }
    });
    await _writeEvents(provider, current);
    if (nextDeltaLink) {
      await _writeAuth(provider, MICROSOFT_AUTH_PATH, { ...auth, sync_state: { delta_link: nextDeltaLink, updated_at: now } });
    }
    return { ok: true, imported, updated, deleted, total: events.length, incremental: true, fallback_full: fallbackFull };
  }

  async function _microsoftPull(provider, body) {
    const user = String(body?.user || '').trim();
    if (body?.incremental) return _microsoftPullIncremental(provider, user);
    return _microsoftPullFull(provider, user);
  }

  function _microsoftEventBody(row) {
    const start = row.start || new Date().toISOString().slice(0, 16);
    const end = row.end || start;
    const body = {
      subject: row.title || '無題',
      body: { contentType: 'text', content: row.description || '' },
      location: { displayName: row.location || '' },
      isAllDay: !!row.all_day,
    };
    if (row.all_day) {
      const startDate = _dateOnly(start);
      const endDate = _localAllDayEndToGoogle(startDate, _dateOnly(end || start));
      body.start = { dateTime: startDate + 'T00:00:00', timeZone: 'Asia/Tokyo' };
      body.end = { dateTime: endDate + 'T00:00:00', timeZone: 'Asia/Tokyo' };
    } else {
      body.start = { dateTime: start.slice(0, 19), timeZone: 'Asia/Tokyo' };
      body.end = { dateTime: (end || start).slice(0, 19), timeZone: 'Asia/Tokyo' };
    }
    return body;
  }

  async function _microsoftPush(provider, body) {
    const user = String(body?.user || '').trim();
    const auth = await _microsoftAccessToken(provider);
    const rows = await _readEvents(provider);
    let pushed = 0;
    const now = _nowIso();
    for (const row of rows) {
      if (!_isLocalUnsent(row, user) || !row.start) continue;
      try {
        const result = await _graphJson('POST', '/me/events', auth.access_token, _microsoftEventBody(row));
        if (!result.id) continue;
        row.external_id = result.id;
        row.calendar_source = 'microsoft';
        row.color = '#0078d4';
        row.url = result.webLink || '';
        row.modified = now;
        pushed += 1;
      } catch {
        // Desktop側と同様、1件の送信失敗で全体を止めない（他の未送信イベントの送信を続ける）
      }
    }
    await _writeEvents(provider, rows);
    return { ok: true, pushed };
  }

  // ============================================================
  // ステータス・ハンドラ登録
  // ============================================================

  async function _statusPayload(provider) {
    // Google ToDoは gb-cal-cloud-tasks.js（Phase 5・案A残り項目）が実装する。
    // 読み込み順に依存させないよう任意結合にし、未読込時は「利用不可」を返す。
    const googleTasksStatus = window.MeldexCalCloudTasks?._internal?.statusPayload;
    const [google, microsoft, googleTasks] = await Promise.all([
      _readAuth(provider, GOOGLE_AUTH_PATH),
      _readAuth(provider, MICROSOFT_AUTH_PATH),
      typeof googleTasksStatus === 'function' ? googleTasksStatus(provider) : Promise.resolve({ available: false, connected: false }),
    ]);
    return {
      google: { available: true, connected: !!google?.refresh_token },
      googleTasks,
      microsoft: { available: true, connected: !!microsoft?.refresh_token, tenant: microsoft?.tenant || 'common' },
      ical: { available: true, connected: false, supports_url_auth: false },
    };
  }

  async function _calCloudSyncHandler({ method, body, pathname }) {
    if (pathname === '/cal/sync/status' && method === 'GET') {
      return _statusPayload(await _requirePwaProvider('read'));
    }
    if (pathname === '/cal/sync/google/pull' && method === 'POST') {
      return _googlePull(await _requirePwaProvider('readwrite'), body || {});
    }
    if (pathname === '/cal/sync/google/push' && method === 'POST') {
      return _googlePush(await _requirePwaProvider('readwrite'), body || {});
    }
    if (pathname === '/cal/sync/microsoft/pull' && method === 'POST') {
      return _microsoftPull(await _requirePwaProvider('readwrite'), body || {});
    }
    if (pathname === '/cal/sync/microsoft/push' && method === 'POST') {
      return _microsoftPush(await _requirePwaProvider('readwrite'), body || {});
    }
    return NOT_HANDLED;
  }
  handlers.push(_calCloudSyncHandler);

  // ============================================================
  // 認証（UI直接呼び出し用。ポップアップをクリックハンドラから同期的に開けるよう
  // apiPost経由の間接呼び出しにはしない）
  // ============================================================

  async function authorizeGoogle({ clientId, clientSecret, popup }) {
    const id = String(clientId || '').trim();
    const secret = String(clientSecret || '').trim();
    const { token } = await _oauth().google.authorize({ clientId: id, clientSecret: secret, popup });
    const provider = await _requirePwaProvider('readwrite');
    const existing = await _readAuth(provider, GOOGLE_AUTH_PATH);
    await _writeAuth(provider, GOOGLE_AUTH_PATH, {
      client_id: id,
      client_secret: secret,
      access_token: token.access_token,
      refresh_token: token.refresh_token || existing?.refresh_token || '',
      expires_at: Date.now() + Math.max(60, Number(token.expires_in || 3600)) * 1000,
      scope: token.scope || '',
      sync_state: existing?.sync_state || null,
      connected_at: _nowIso(),
    });
    return { ok: true, message: 'Google Calendar認証成功' };
  }

  async function authorizeMicrosoft({ clientId, tenant, popup }) {
    const id = String(clientId || '').trim();
    const tenantValue = String(tenant || 'common').trim() || 'common';
    const { token } = await _oauth().microsoft.authorize({ clientId: id, tenant: tenantValue, popup });
    const provider = await _requirePwaProvider('readwrite');
    const existing = await _readAuth(provider, MICROSOFT_AUTH_PATH);
    await _writeAuth(provider, MICROSOFT_AUTH_PATH, {
      client_id: id,
      tenant: tenantValue,
      access_token: token.access_token,
      refresh_token: token.refresh_token || existing?.refresh_token || '',
      expires_at: Date.now() + Math.max(60, Number(token.expires_in || 3600)) * 1000,
      scope: token.scope || '',
      sync_state: existing?.sync_state || null,
      connected_at: _nowIso(),
    });
    return { ok: true, message: 'Microsoft Calendar認証成功' };
  }

  window.MeldexCalCloudSync = {
    EVENTS_PATH,
    GOOGLE_AUTH_PATH,
    MICROSOFT_AUTH_PATH,
    authorizeGoogle,
    authorizeMicrosoft,
    // テスト・診断用に内部関数も公開する（gb-tool-calendar-sync.js からは通常
    // apiPost('/cal/sync/...') 経由でハンドラを叩くため、直接呼ぶのは認証時のみ）。
    _internal: {
      statusPayload: _statusPayload,
      googlePull: _googlePull,
      googlePush: _googlePush,
      microsoftPull: _microsoftPull,
      microsoftPush: _microsoftPush,
      readAuth: _readAuth,
      writeAuth: _writeAuth,
      readEvents: _readEvents,
      writeEvents: _writeEvents,
      googleAllDayEndToLocal: _googleAllDayEndToLocal,
      localAllDayEndToGoogle: _localAllDayEndToGoogle,
    },
  };
})();

;

/* === gb-cal-cloud-tasks.js === */
;
/* ==============================
   gb-cal-cloud-tasks.js: Cloud（Dropboxモード）向け Google ToDo（Google Tasks API）同期エンジン

   Cloud外部カレンダー連携 Phase 5・案A（app/docs/production-management-ux-improvement-plan-2026-08-04.md §6.5）の
   残り項目。Desktop側 meldex_api_google_tasks.py の対応付け・重複防止・完了状態の
   同期方向ロジックを仕様の正とし、ブラウザ完結（サーバー無し）版として同一挙動になる
   よう移植する。gb-cal-cloud-sync.js と同じ設計パターンに厳密に合わせる。

   認証: gb-cal-oauth-browser.js のPKCE+ポップアップ共通フロー（Google Calendarと共通）を
   使うが、トークンはカレンダー接続とは完全に独立して保存する（スコープが異なるため。
   Client ID/Secretも別入力・別トークンファイル）。gb-cal-oauth-browser.js の
   authorizeGoogle は Client ID/Secret 双方が必須のため、CloudのGoogle ToDoも
   Desktop版（Client IDのみ）とは異なりSecret入力を必須にする
   （gb-cal-oauth-browser.js は他レーンの契約のため変更しない）。

   このファイルは __MeldexPwaDataAccessExtensions ハンドラとして
   `/cal/sync/google/tasks/sync` を横取りする。Meldex.html 側で
   gb-data-access-dropbox-expanded.js より前に読み込むことで、同ファイルの
   「Cloud BETAでは無効です」catch-all より先にこのハンドラが応答する
   （gb-cal-cloud-sync.js と同じ配線パターン）。

   ローカルのToDo本体は /cal/tasks CRUD（gb-data-access-dropbox-expanded.part01.js の
   _calendarList/_calendarCreate/_calendarUpdate/_calendarDelete）が管理する
   _calendar/tasks.json をそのまま読み書きする（同期専用の別ストアは持たない。
   ToDoリストUIが見ているデータと完全に同じ行を同期対象にするため）。

   ローカル削除のGoogleへの反映について: Desktop版はSQLiteの削除トリガーで
   cal_task_sync_deletions テーブルへ記録するが、Cloud版は _calendarDelete
   （他レーンの成果物のため直接編集しない）にフックできない。代わりに、
   直前の同期で作成した「同期済みID対応表」（google_tasks_auth.json の
   task_links）と現在の _calendar/tasks.json を突き合わせ、対応表にあった
   idがローカルから消えていれば「ローカルで削除された」とみなしてGoogle側を
   削除する（差分スナップショット方式）。

   スコープ不足時の再認証: 保存済みトークンのscopeに'tasks'が含まれない場合
   （例: 何らかの理由で別スコープのトークンが混入した場合）は、アクセストークン・
   リフレッシュトークンを破棄して再ログインを促す（reauth_requiredと同じ導線）。

   秘密情報はログ出力しない。トークンをURLへ載せない。
   ============================== */
(function () {
  'use strict';

  const internals = window.__MeldexPwaDataAccessInternals;
  const handlers = window.__MeldexPwaDataAccessExtensions;
  if (!internals || !Array.isArray(handlers)) return;

  const { NOT_HANDLED, _joinPath, _requirePwaProvider, _directoryHandle, _readJsonSafe } = internals;

  const CAL_DIR = '_calendar';
  const TASKS_PATH = _joinPath(CAL_DIR, 'tasks.json');
  const GOOGLE_TASKS_AUTH_PATH = _joinPath(CAL_DIR, 'google_tasks_auth.json');
  const GOOGLE_TASKS_SCOPE = 'https://www.googleapis.com/auth/tasks';
  const GOOGLE_TASKS_LIST_TITLE = 'Meldex';
  const GOOGLE_TASKS_SOURCE = 'google_tasks';
  const TASKS_API_BASE = 'https://tasks.googleapis.com/tasks/v1';
  const TOKEN_EARLY_REFRESH_MS = 60 * 1000;

  function _oauth() {
    const api = window.MeldexCalOAuthBrowser;
    if (!api) throw new Error('gb-cal-oauth-browser.js が読み込まれていません');
    return api;
  }

  function _httpError(message, status, code) {
    const err = new Error(message);
    err.status = status || 500;
    if (code) err.code = code;
    return err;
  }

  function _randomId(prefix) {
    const rand = (globalThis.crypto?.randomUUID?.() || String(Math.random()).slice(2)) + Date.now().toString(36);
    return `${prefix || 'task'}-${rand}`;
  }

  function _nowIso() {
    return new Date().toISOString();
  }

  // ============================================================
  // ストレージ（_calendar/ 配下のJSON。tasks.json は /cal/tasks CRUD と共有）
  // ============================================================

  // コミット前レビュー指摘 #10: gb-cal-cloud-sync.js と同じ理由・同じ仕組みで、
  // client_secret・access_token・refresh_token は gb-cal-oauth-store.js
  // （IndexedDB。gb-llm-keys-store.js の local-device モードと同じ保護水準）へ保存し、
  // Dropbox上の平文JSONには残さない。
  function _tokenKeyForPath(path) {
    if (path === GOOGLE_TASKS_AUTH_PATH) return 'google-tasks';
    return 'cal-cloud-tasks:' + String(path || '');
  }

  async function _readAuth(provider, path) {
    const stored = (await _readJsonSafe(provider, path, null)) || null;
    const store = window.MeldexCalOAuthTokenStore;
    if (!store) return stored; // トークンストア未読込時は安全側フォールバックとして旧挙動を維持
    const tokenKey = _tokenKeyForPath(path);
    let secrets = await store.getSecrets(tokenKey).catch(() => null);
    if (!secrets) {
      // 読み替え互換: 旧位置（Dropbox平文JSON）に秘密フィールドが残っていれば、
      // 新位置（IndexedDB）へ一度だけ移してから旧位置の平文フィールドを削除する。
      const legacySecrets = store.extractSecretFields(stored || {});
      if (store.hasAnySecretValue(legacySecrets)) {
        await store.setSecrets(tokenKey, legacySecrets).catch(() => {});
        secrets = legacySecrets;
        if (stored) {
          await _directoryHandle(provider, CAL_DIR, true);
          await provider.writeJson(path, store.stripSecretFields(stored)).catch(() => {});
        }
      }
    }
    if (!stored && !store.hasAnySecretValue(secrets)) return null;
    return { ...store.stripSecretFields(stored || {}), ...(secrets || {}) };
  }

  async function _writeAuth(provider, path, payload) {
    const store = window.MeldexCalOAuthTokenStore;
    let metadata = payload;
    if (store) {
      const tokenKey = _tokenKeyForPath(path);
      const secrets = store.extractSecretFields(payload);
      if (Object.keys(secrets).length) await store.setSecrets(tokenKey, secrets);
      metadata = store.stripSecretFields(payload);
    }
    await _directoryHandle(provider, CAL_DIR, true);
    await provider.writeJson(path, metadata);
  }

  async function _readTasks(provider) {
    const data = await _readJsonSafe(provider, TASKS_PATH, []);
    return Array.isArray(data) ? data : [];
  }

  async function _writeTasks(provider, rows) {
    await _directoryHandle(provider, CAL_DIR, true);
    await provider.writeJson(TASKS_PATH, Array.isArray(rows) ? rows : []);
  }

  function _findExternalTaskRow(rows, externalId, user) {
    if (!externalId) return null;
    const candidates = rows.filter((row) => (
      String(row.external_id || '') === externalId
      && String(row.task_source || '') === GOOGLE_TASKS_SOURCE
      && (!user || row.user === user || !row.user)
    ));
    if (!candidates.length) return null;
    return candidates.find((row) => row.user === user) || candidates[0];
  }

  function _relevantLocalRows(rows, user) {
    return rows.filter((row) => {
      const source = String(row.task_source || '');
      const sourceOk = !source || source === 'local' || source === GOOGLE_TASKS_SOURCE;
      const userOk = !user || row.user === user;
      return sourceOk && userOk;
    });
  }

  // ============================================================
  // 日時・ステータス・本文の変換（Desktop側 _google_tasks_to_local_iso /
  // _google_tasks_external_is_newer / _google_tasks_local_needs_push /
  // _google_tasks_status_to_meldex / _google_tasks_body_from_task と同じ意味論）
  // ============================================================

  function _pad2(n) { return String(n).padStart(2, '0'); }

  function _localIsoSeconds(date) {
    return `${date.getFullYear()}-${_pad2(date.getMonth() + 1)}-${_pad2(date.getDate())}`
      + `T${_pad2(date.getHours())}:${_pad2(date.getMinutes())}:${_pad2(date.getSeconds())}`;
  }

  function _tasksToLocalIso(value) {
    const raw = String(value || '').trim();
    if (!raw) return '';
    const date = new Date(raw);
    if (Number.isNaN(date.getTime())) return raw.slice(0, 19);
    return _localIsoSeconds(date);
  }

  function _tasksDt(value) {
    const raw = String(value || '').trim();
    if (!raw) return null;
    const date = new Date(raw);
    return Number.isNaN(date.getTime()) ? null : date;
  }

  function _tasksExternalIsNewer(row, remoteUpdatedIso) {
    const remote = _tasksDt(remoteUpdatedIso);
    const local = _tasksDt(row?.modified);
    if (!remote) return true;
    if (!local) return true;
    return remote.getTime() > local.getTime();
  }

  function _tasksLocalNeedsPush(row) {
    if (!String(row?.external_id || '').trim()) return true;
    const local = _tasksDt(row?.modified);
    const synced = _tasksDt(row?.last_synced);
    if (!synced) return true;
    if (!local) return false;
    return local.getTime() > synced.getTime();
  }

  function _tasksDueToDate(value) {
    const raw = String(value || '').trim();
    return raw.length >= 10 ? raw.slice(0, 10) : '';
  }

  function _tasksStatusToMeldex(remoteStatus, localStatus) {
    if (String(remoteStatus || '') === 'completed') return 'done';
    const local = String(localStatus || '');
    if (['backlog', 'todo', 'in_progress', 'review', 'done'].includes(local)) return local;
    return 'todo';
  }

  function _tasksBodyFromRow(row, { includeClear } = {}) {
    const body = {
      title: String(row?.title || '無題'),
      notes: String(row?.description || ''),
      status: String(row?.status || '') === 'done' ? 'completed' : 'needsAction',
    };
    const due = String(row?.due_date || '').trim().slice(0, 10);
    if (due) body.due = due + 'T00:00:00.000Z';
    else if (includeClear) body.due = null;
    return body;
  }

  // ============================================================
  // Google Tasks API（fetch直叩き。gb-cal-cloud-sync.js の _graphJson/_googleEventsPage と同じ形）
  // ============================================================

  function _tasksQuote(value) { return encodeURIComponent(String(value || '')); }

  function _tasksRemotePath(tasklistId, taskId) {
    const base = '/lists/' + _tasksQuote(tasklistId) + '/tasks';
    return taskId ? base + '/' + _tasksQuote(taskId) : base;
  }

  async function _tasksApiJson(accessToken, method, pathOrUrl, body, options = {}) {
    const url = pathOrUrl.startsWith('https://') ? pathOrUrl : TASKS_API_BASE + pathOrUrl;
    const headers = { Authorization: 'Bearer ' + accessToken, Accept: 'application/json' };
    const init = { method, headers };
    if (body !== undefined) { init.body = JSON.stringify(body); headers['Content-Type'] = 'application/json'; }
    const response = await fetch(url, init);
    if (options.allow404 && response.status === 404) return { missing: true };
    if (!response.ok) {
      const detail = await response.json().catch(() => null);
      throw _httpError(detail?.error?.message || `Google Tasks APIエラー(${response.status})`, response.status);
    }
    const text = await response.text();
    return text ? JSON.parse(text) : {};
  }

  async function _tasksPagedItems(accessToken, path) {
    const items = [];
    let pageToken = '';
    for (;;) {
      const sep = path.includes('?') ? '&' : '?';
      const pagePath = path + (pageToken ? sep + 'pageToken=' + encodeURIComponent(pageToken) : '');
      const data = await _tasksApiJson(accessToken, 'GET', pagePath);
      items.push(...(data.items || []));
      pageToken = data.nextPageToken || '';
      if (!pageToken) return items;
    }
  }

  async function _tasksRemoteItems(accessToken, tasklistId) {
    const query = 'showCompleted=true&showDeleted=true&showHidden=true&maxResults=100';
    return _tasksPagedItems(accessToken, _tasksRemotePath(tasklistId) + '?' + query);
  }

  // ============================================================
  // 認証・トークン更新・スコープ確認
  // ============================================================

  async function _googleTasksAccessToken(provider) {
    const auth = await _readAuth(provider, GOOGLE_TASKS_AUTH_PATH);
    if (!auth?.refresh_token) throw _httpError('Google ToDo未接続', 400, 'not_connected');
    if (auth.access_token && Number(auth.expires_at || 0) > Date.now() + TOKEN_EARLY_REFRESH_MS) return auth;
    try {
      const refreshed = await _oauth().google.refreshToken({
        refreshToken: auth.refresh_token, clientId: auth.client_id, clientSecret: auth.client_secret,
      });
      const next = {
        ...auth,
        access_token: refreshed.access_token,
        expires_at: Date.now() + Math.max(60, Number(refreshed.expires_in || 3600)) * 1000,
        refresh_token: refreshed.refresh_token || auth.refresh_token,
        scope: refreshed.scope || auth.scope || '',
      };
      await _writeAuth(provider, GOOGLE_TASKS_AUTH_PATH, next);
      return next;
    } catch {
      // gb-cal-cloud-sync.js の _googleAccessToken と同じ理由でrefresh_tokenごと破棄し、
      // 次回 /cal/sync/status で connected:false に戻して再認証導線（ログインフォーム
      // 再表示）につなげる。
      await _writeAuth(provider, GOOGLE_TASKS_AUTH_PATH, { ...auth, access_token: '', refresh_token: '', expires_at: 0 }).catch(() => {});
      throw _httpError('Google ToDoの認証が失効しました。もう一度ログインしてください', 400, 'reauth_required');
    }
  }

  async function _requireTasksScope(provider, auth) {
    const scope = String(auth?.scope || '');
    if (scope && !scope.includes('tasks')) {
      // この接続はtasksスコープを含まないトークンで保存されている（再認証導線）。
      // access/refresh_tokenを破棄し、次回のstatusで未接続に戻す。
      await _writeAuth(provider, GOOGLE_TASKS_AUTH_PATH, { ...auth, access_token: '', refresh_token: '', expires_at: 0 }).catch(() => {});
      throw _httpError('この接続にはGoogle ToDoの権限が含まれていません。もう一度ログインしてください', 400, 'insufficient_scope');
    }
  }

  async function _googleTasksEnsureList(provider, auth) {
    if (auth.tasklist_id) return auth.tasklist_id;
    const lists = await _tasksPagedItems(auth.access_token, '/users/@me/lists?maxResults=100');
    const existing = lists.find((item) => item.title === GOOGLE_TASKS_LIST_TITLE && item.id);
    if (existing) {
      await _writeAuth(provider, GOOGLE_TASKS_AUTH_PATH, { ...auth, tasklist_id: existing.id, tasklist_title: GOOGLE_TASKS_LIST_TITLE });
      return existing.id;
    }
    const created = await _tasksApiJson(auth.access_token, 'POST', '/users/@me/lists', { title: GOOGLE_TASKS_LIST_TITLE });
    if (!created.id) throw _httpError('Google ToDoリストを作成できませんでした', 502);
    await _writeAuth(provider, GOOGLE_TASKS_AUTH_PATH, { ...auth, tasklist_id: created.id, tasklist_title: GOOGLE_TASKS_LIST_TITLE });
    return created.id;
  }

  // ============================================================
  // pull（Google → ローカル）
  // ============================================================

  function _applyRemoteTask(rows, remote, user, now) {
    const extId = String(remote?.id || '').trim();
    if (!extId) return 'skipped';
    const existing = _findExternalTaskRow(rows, extId, user);
    const remoteUpdated = _tasksToLocalIso(remote.updated) || now;
    if (remote.deleted) {
      if (existing && _tasksExternalIsNewer(existing, remoteUpdated)) {
        rows.splice(rows.indexOf(existing), 1);
        return 'deleted';
      }
      return 'skipped';
    }
    const title = String(remote.title || '無題');
    const description = String(remote.notes || '');
    const dueDate = _tasksDueToDate(remote.due || '');
    if (existing) {
      if (!_tasksExternalIsNewer(existing, remoteUpdated)) return 'skipped';
      Object.assign(existing, {
        title, description, due_date: dueDate,
        status: _tasksStatusToMeldex(remote.status, existing.status),
        external_id: extId, task_source: GOOGLE_TASKS_SOURCE,
        last_synced: remoteUpdated, modified: remoteUpdated,
      });
      return 'updated';
    }
    rows.push({
      id: _randomId('gtask'), title, description,
      status: _tasksStatusToMeldex(remote.status, ''),
      priority: 'medium', due_date: dueDate,
      assignee: '', labels: [], parent_id: '',
      estimated_hours: 0, actual_hours: 0, related_path: '', sort_order: 0,
      user: user || 'anonymous', creator: user || 'anonymous',
      external_id: extId, task_source: GOOGLE_TASKS_SOURCE,
      last_synced: remoteUpdated, created: remoteUpdated, modified: remoteUpdated,
    });
    return 'imported';
  }

  async function _pullGoogleTasks(rows, auth, tasklistId, user, now) {
    const items = await _tasksRemoteItems(auth.access_token, tasklistId);
    let imported = 0; let updated = 0; let deleted = 0; let skipped = 0;
    items.forEach((remote) => {
      const action = _applyRemoteTask(rows, remote, user, now);
      if (action === 'imported') imported += 1;
      else if (action === 'updated') updated += 1;
      else if (action === 'deleted') deleted += 1;
      else skipped += 1;
    });
    return { imported, updated, deleted, skipped, total: items.length };
  }

  // ============================================================
  // push（ローカル → Google）。削除の反映は取得より先に行う
  // （Desktop側 _sync_google_tasks と同じ順序。逆順だと、ローカルで削除済みの
  //   タスクがGoogle側にまだ残っている状態のまま取得され、再インポートされて
  //   一時的に復活してしまう）
  // ============================================================

  function _linksFromRows(rows, user) {
    return rows
      .filter((row) => String(row.task_source || '') === GOOGLE_TASKS_SOURCE && row.external_id)
      .filter((row) => !user || row.user === user)
      .map((row) => ({ id: row.id, external_id: row.external_id, user: row.user || '' }));
  }

  function _mergeLinks(previousLinks, currentUserLinks, user) {
    const others = user ? previousLinks.filter((link) => link.user !== user) : [];
    return [...others, ...currentUserLinks];
  }

  async function _pushDeletedLocal(auth, tasklistId, rows, user) {
    const previousLinks = Array.isArray(auth.task_links) ? auth.task_links : [];
    const relevant = user ? previousLinks.filter((link) => link.user === user) : previousLinks;
    const currentIds = new Set(rows.map((row) => row.id));
    let deleted = 0;
    for (const link of relevant) {
      if (currentIds.has(link.id) || !link.external_id) continue;
      await _tasksApiJson(auth.access_token, 'DELETE', _tasksRemotePath(tasklistId, link.external_id), undefined, { allow404: true });
      deleted += 1;
    }
    return deleted;
  }

  async function _pushLocalTasks(auth, tasklistId, rows, user, now) {
    const result = { pushed: 0, updated: 0, skipped: 0 };
    for (const row of _relevantLocalRows(rows, user)) {
      const externalId = String(row.external_id || '').trim();
      if (externalId && !_tasksLocalNeedsPush(row)) { result.skipped += 1; continue; }
      let response;
      if (externalId) {
        response = await _tasksApiJson(auth.access_token, 'PATCH', _tasksRemotePath(tasklistId, externalId), _tasksBodyFromRow(row, { includeClear: true }), { allow404: true });
        if (response.missing) {
          response = await _tasksApiJson(auth.access_token, 'POST', _tasksRemotePath(tasklistId), _tasksBodyFromRow(row));
          result.pushed += 1;
        } else {
          result.updated += 1;
        }
      } else {
        response = await _tasksApiJson(auth.access_token, 'POST', _tasksRemotePath(tasklistId), _tasksBodyFromRow(row));
        result.pushed += 1;
      }
      const remoteId = response.id || externalId;
      const synced = _tasksToLocalIso(response.updated) || now;
      row.external_id = remoteId;
      row.task_source = GOOGLE_TASKS_SOURCE;
      row.last_synced = synced;
      row.modified = synced;
    }
    return result;
  }

  // ============================================================
  // 同期オーケストレーション
  // ============================================================

  async function _syncGoogleTasks(provider, body) {
    const user = String(body?.user || '').trim();
    const auth0 = await _googleTasksAccessToken(provider);
    await _requireTasksScope(provider, auth0);
    const tasklistId = await _googleTasksEnsureList(provider, auth0);
    const auth = (await _readAuth(provider, GOOGLE_TASKS_AUTH_PATH)) || auth0;
    const rows = await _readTasks(provider);
    const now = _nowIso();

    const deletedRemote = await _pushDeletedLocal(auth, tasklistId, rows, user);
    const pull = await _pullGoogleTasks(rows, auth, tasklistId, user, now);
    const push = await _pushLocalTasks(auth, tasklistId, rows, user, now);

    await _writeTasks(provider, rows);

    const currentUserLinks = _linksFromRows(rows, user);
    const previousLinks = Array.isArray(auth.task_links) ? auth.task_links : [];
    await _writeAuth(provider, GOOGLE_TASKS_AUTH_PATH, { ...auth, task_links: _mergeLinks(previousLinks, currentUserLinks, user) });

    return {
      ok: true,
      tasklist_id: tasklistId,
      pull,
      push,
      deleted_remote: deletedRemote,
      imported: pull.imported,
      updated: pull.updated + push.updated,
      pushed: push.pushed,
      deleted: pull.deleted,
      skipped: pull.skipped + push.skipped,
      total: pull.total,
    };
  }

  // ============================================================
  // ステータス・ハンドラ登録
  // ============================================================

  async function _statusPayload(provider) {
    const auth = await _readAuth(provider, GOOGLE_TASKS_AUTH_PATH);
    return {
      available: true,
      connected: !!auth?.refresh_token,
      listTitle: auth?.tasklist_title || GOOGLE_TASKS_LIST_TITLE,
    };
  }

  async function _calCloudTasksHandler({ method, body, pathname }) {
    if (pathname === '/cal/sync/google/tasks/sync' && method === 'POST') {
      return _syncGoogleTasks(await _requirePwaProvider('readwrite'), body || {});
    }
    return NOT_HANDLED;
  }
  handlers.push(_calCloudTasksHandler);

  // ============================================================
  // 認証（UI直接呼び出し用。gb-cal-cloud-sync.js の authorizeGoogle/authorizeMicrosoft と
  // 同じ理由でポップアップをクリックハンドラから同期的に開けるよう、apiPost経由の
  // 間接呼び出しにはしない）
  // ============================================================

  async function authorizeGoogleTasks({ clientId, clientSecret, popup }) {
    const id = String(clientId || '').trim();
    const secret = String(clientSecret || '').trim();
    const { token } = await _oauth().google.authorize({ clientId: id, clientSecret: secret, scope: GOOGLE_TASKS_SCOPE, popup });
    const provider = await _requirePwaProvider('readwrite');
    const existing = await _readAuth(provider, GOOGLE_TASKS_AUTH_PATH);
    await _writeAuth(provider, GOOGLE_TASKS_AUTH_PATH, {
      client_id: id,
      client_secret: secret,
      access_token: token.access_token,
      refresh_token: token.refresh_token || existing?.refresh_token || '',
      expires_at: Date.now() + Math.max(60, Number(token.expires_in || 3600)) * 1000,
      scope: token.scope || '',
      tasklist_id: existing?.tasklist_id || '',
      tasklist_title: existing?.tasklist_title || GOOGLE_TASKS_LIST_TITLE,
      task_links: existing?.task_links || [],
      connected_at: _nowIso(),
    });
    return { ok: true, message: 'Google ToDo認証成功' };
  }

  window.MeldexCalCloudTasks = {
    TASKS_PATH,
    GOOGLE_TASKS_AUTH_PATH,
    GOOGLE_TASKS_SCOPE,
    authorizeGoogleTasks,
    // テスト・診断用に内部関数も公開する（gb-cal-cloud-sync.js の _internal と同じ方針）。
    _internal: {
      statusPayload: _statusPayload,
      syncGoogleTasks: _syncGoogleTasks,
      readAuth: _readAuth,
      writeAuth: _writeAuth,
      readTasks: _readTasks,
      writeTasks: _writeTasks,
    },
  };
})();

;

/* === gb-cal-ics-subscribe.js === */
;
/* ==============================
   gb-cal-ics-subscribe.js: iPhone向けICS購読（読み取り専用）

   Cloud外部カレンダー連携 Phase 5・案A（app/docs/production-management-ux-improvement-plan-2026-08-04.md §6.5）。
   Meldexのカレンダー（表示対象イベント）を .ics としてDropboxの管理領域へ
   書き出し、Dropboxの共有リンクを「照会（購読）カレンダー」としてiPhone等へ
   登録してもらう。書き出しは既存の /cal/sync/ical/export（gb-data-access-dropbox
   -expanded.part02.js の _handleCalendar）が返すiCal本文を再利用し、iCal生成
   ロジックを重複させない。

   共有リンク自動作成は Dropbox API sharing.write スコープに依存する（gb-config.js
   参照）。このスコープは2026-08-04に新規追加したため、既存の接続セッションは
   再接続するまで持たない。作成に失敗した場合は例外を投げるので、呼び出し側
   （gb-tool-calendar-sync.js）はファイルパスを示す手動作成の案内へフォールバックする。
   ============================== */
(function () {
  'use strict';

  const ICS_RELATIVE_PATH = '_calendar/meldex-subscribe.ics';
  const AUTO_REFRESH_FLAG_KEY = 'meldex-cal-ics-subscription-enabled';

  function _dropboxAuth() {
    const auth = window.MeldexDropboxAuth;
    if (!auth) throw new Error('gb-dropbox-auth.js が読み込まれていません');
    return auth;
  }

  function _rootResolver() {
    const resolver = window.MeldexDropboxManagementRootResolver;
    if (!resolver) throw new Error('gb-dropbox-management-root-resolver.js が読み込まれていません');
    return resolver;
  }

  function _joinDropboxPath(root, relative) {
    const base = String(root || '').replace(/\/+$/, '');
    const rel = String(relative || '').replace(/^\/+/, '');
    return `${base}/${rel}`;
  }

  // ============================================================
  // .ics 書き出し（既存の /cal/sync/ical/export を再利用する）
  // ============================================================

  async function refreshIcsFile() {
    if (!window.MeldexDataAccess?.requestJson) throw new Error('Cloud保存APIが初期化されていません');
    const exported = await window.MeldexDataAccess.requestJson('/cal/sync/ical/export');
    if (!exported?.content) throw new Error('カレンダーの書き出しに失敗しました');
    const provider = window.MeldexStorageAdapter?.getProvider?.();
    if (!provider) throw new Error('Dropbox provider が未初期化です');
    const internals = window.__MeldexPwaDataAccessInternals;
    if (internals?._directoryHandle) await internals._directoryHandle(provider, '_calendar', true);
    await provider.writeText(ICS_RELATIVE_PATH, String(exported.content || ''));
    return { ok: true, path: ICS_RELATIVE_PATH, bytes: exported.content.length };
  }

  // ============================================================
  // Dropbox 共有リンク（sharing.write スコープが必要。無ければ例外を投げる）
  // ============================================================

  function _toDirectDownloadUrl(shareUrl) {
    try {
      const url = new URL(shareUrl);
      url.searchParams.set('dl', '1');
      return url.toString();
    } catch {
      return shareUrl;
    }
  }

  function _toWebcalUrl(directUrl) {
    return directUrl.replace(/^https?:\/\//i, 'webcal://');
  }

  async function _absoluteIcsPath(provider) {
    const { rootPath, namespaceKind } = await _rootResolver().resolveConnectionInfo(provider);
    return { path: _joinDropboxPath(rootPath, ICS_RELATIVE_PATH), namespaceKind };
  }

  async function _existingSharedLink(path, namespaceKind) {
    const result = await _dropboxAuth().apiRpc(
      'sharing/list_shared_links',
      { path, direct_only: true },
      { namespaceKind },
    );
    const link = (result?.links || [])[0];
    return link?.url || '';
  }

  async function _createSharedLink(path, namespaceKind) {
    const result = await _dropboxAuth().apiRpc(
      'sharing/create_shared_link_with_settings',
      { path, settings: { requested_visibility: 'public' } },
      { namespaceKind },
    );
    return result?.url || '';
  }

  async function createSubscriptionLink() {
    await refreshIcsFile();
    const provider = window.MeldexStorageAdapter?.getProvider?.();
    if (!provider) throw new Error('Dropbox provider が未初期化です');
    const { path, namespaceKind } = await _absoluteIcsPath(provider);
    let shareUrl = '';
    try {
      shareUrl = await _existingSharedLink(path, namespaceKind);
      if (!shareUrl) shareUrl = await _createSharedLink(path, namespaceKind);
    } catch (err) {
      const message = String(err?.message || err || '');
      const scopeIssue = /scope|permission|not_authorized/i.test(message);
      const wrapped = new Error(
        scopeIssue
          ? 'Dropboxの共有権限が不足しています。設定でDropbox接続を一度解除し、再接続してください（購読リンクの自動作成には追加の権限が必要です）'
          : `Dropbox共有リンクの作成に失敗しました: ${message}`,
      );
      wrapped.cause = err;
      wrapped.code = scopeIssue ? 'missing_scope' : 'link_create_failed';
      wrapped.manualPath = path;
      throw wrapped;
    }
    try { localStorage.setItem(AUTO_REFRESH_FLAG_KEY, '1'); } catch {}
    const direct = _toDirectDownloadUrl(shareUrl);
    return {
      ok: true,
      relativePath: ICS_RELATIVE_PATH,
      absolutePath: path,
      shareUrl,
      directUrl: direct,
      webcalUrl: _toWebcalUrl(direct),
    };
  }

  function isAutoRefreshEnabled() {
    try { return localStorage.getItem(AUTO_REFRESH_FLAG_KEY) === '1'; } catch { return false; }
  }

  // コミット前レビュー指摘 #4: この関数自体は「購読用ファイルの自動更新が有効なら
  // 書き出し直す」だけの単発処理。呼び出し元（gb-tool-calendar-sync.js の
  // _googleCalAutoSync / _microsoftCalAutoSync 成功後フック）が5分間隔で叩くため、
  // 同一実行が重ならないよう多重実行ガードを持つ。
  let _icsAutoRefreshInFlight = false;

  async function autoRefreshIfEnabled() {
    if (!isAutoRefreshEnabled()) return { ok: true, skipped: true };
    if (_icsAutoRefreshInFlight) return { ok: true, skipped: true, inFlight: true };
    _icsAutoRefreshInFlight = true;
    try {
      return await refreshIcsFile();
    } catch (err) {
      console.warn('[MeldexCalIcsSubscribe] 購読用.icsファイルの自動更新に失敗しました:', err);
      return { ok: false, error: err?.message || String(err) };
    } finally {
      _icsAutoRefreshInFlight = false;
    }
  }

  window.MeldexCalIcsSubscribe = {
    ICS_RELATIVE_PATH,
    refreshIcsFile,
    createSubscriptionLink,
    isAutoRefreshEnabled,
    autoRefreshIfEnabled,
  };
})();

;

/* === gb-data-access-dropbox-expanded.js === */
;
