  return Object.freeze({
    STATUS,
    APPS,
    ENVIRONMENTS,
    CAPABILITIES,
    ADAPTERS: Object.freeze(ADAPTERS),
    classify,
    getProfile,
    supports,
    assertVisibleAction,
    validateDefinition,
  });
