    if (suppressedEl && (!(ev.relatedTarget instanceof Node) || !suppressedEl.contains(ev.relatedTarget))) {
      clearSuppressed();
    }
    const el = activeEl || pendingEl;
    if (!el) return;
    if (ev.relatedTarget instanceof Node && el.contains(ev.relatedTarget)) return;
