    if (_withinSelector(active, NATIVE_ARROW_SELECTOR)) return;

    const buttons = actionButtons(dialog);
    if (!buttons.length) return; // アクション領域が見つからなければ矢印処理はしない

    const forward = key === 'ArrowRight' || key === 'ArrowDown';
